use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct TokenUsage {
    pub input_tokens: u64,
    pub output_tokens: u64,
    #[serde(default)]
    pub cache_read_tokens: u64,
    #[serde(default)]
    pub cache_write_tokens: u64,
    pub total_tokens: u64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cost_usd: Option<f64>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_default() {
        let usage = TokenUsage::default();
        assert_eq!(usage.input_tokens, 0);
        assert_eq!(usage.total_tokens, 0);
        assert!(usage.cost_usd.is_none());
    }

    #[test]
    fn test_serde_roundtrip() {
        let usage = TokenUsage {
            input_tokens: 1000,
            output_tokens: 500,
            cache_read_tokens: 200,
            cache_write_tokens: 100,
            total_tokens: 1800,
            cost_usd: Some(0.23),
        };
        let json = serde_json::to_string(&usage).unwrap();
        let parsed: TokenUsage = serde_json::from_str(&json).unwrap();
        assert_eq!(usage, parsed);
    }

    #[test]
    fn test_cost_usd_omitted_when_none() {
        let usage = TokenUsage::default();
        let json = serde_json::to_string(&usage).unwrap();
        assert!(!json.contains("cost_usd"));
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use super::token_economics::TokenUsage;

/// A unique identifier for an engram.
/// Generated as UUID v4 hex (no dashes), used as the ref path component.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct EngramId(pub String);

impl EngramId {
    pub fn new() -> Self {
        Self(Uuid::new_v4().as_simple().to_string())
    }

    /// The 2-char prefix used for fanout in refs/engrams/<ab>/<full-id>
    pub fn fanout_prefix(&self) -> &str {
        &self.0[..2]
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl Default for EngramId {
    fn default() -> Self {
        Self::new()
    }
}

impl std::fmt::Display for EngramId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl From<String> for EngramId {
    fn from(s: String) -> Self {
        Self(s)
    }
}

impl From<&str> for EngramId {
    fn from(s: &str) -> Self {
        Self(s.to_string())
    }
}

/// Compact metadata stored as manifest.json in the engram tree.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Manifest {
    pub id: EngramId,
    pub version: u32,
    pub created_at: DateTime<Utc>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub finished_at: Option<DateTime<Utc>>,
    pub agent: AgentInfo,
    #[serde(default)]
    pub git_commits: Vec<String>,
    pub token_usage: TokenUsage,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub summary: Option<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub tags: Vec<String>,
    pub capture_mode: CaptureMode,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct AgentInfo {
    pub name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub version: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum CaptureMode {
    Wrapper,
    Import,
    Sdk,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_engram_id_generation() {
        let id = EngramId::new();
        assert_eq!(id.0.len(), 32); // UUID v4 hex, no dashes
        assert_eq!(id.fanout_prefix().len(), 2);
    }

    #[test]
    fn test_engram_id_display() {
        let id = EngramId("abcdef1234567890abcdef1234567890".into());
        assert_eq!(format!("{id}"), "abcdef1234567890abcdef1234567890");
        assert_eq!(id.fanout_prefix(), "ab");
    }

    #[test]
    fn test_manifest_serde_roundtrip() {
        let manifest = Manifest {
            id: EngramId::new(),
            version: 1,
            created_at: Utc::now(),
            finished_at: Some(Utc::now()),
            agent: AgentInfo {
                name: "claude-code".into(),
                model: Some("claude-sonnet-4-5".into()),
                version: Some("2.1.39".into()),
            },
            git_commits: vec!["abc123".into()],
            token_usage: TokenUsage {
                input_tokens: 1000,
                output_tokens: 500,
                total_tokens: 1500,
                cost_usd: Some(0.23),
                ..Default::default()
            },
            summary: Some("Implemented OAuth2".into()),
            tags: vec!["auth".into()],
            capture_mode: CaptureMode::Wrapper,
        };
        let json = serde_json::to_string_pretty(&manifest).unwrap();
        let parsed: Manifest = serde_json::from_str(&json).unwrap();
        assert_eq!(manifest, parsed);
    }
}

use serde::{Deserialize, Serialize};

use crate::error::CoreError;

/// Structured intent data, stored as intent.md (Markdown) in the engram tree.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Intent {
    pub original_request: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interpreted_goal: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub summary: Option<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub dead_ends: Vec<DeadEnd>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub decisions: Vec<Decision>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct DeadEnd {
    pub approach: String,
    pub reason: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Decision {
    pub description: String,
    pub rationale: String,
}

impl Intent {
    /// Render as Markdown for storage as intent.md
    pub fn to_markdown(&self) -> String {
        let mut md = String::new();

        md.push_str("# Intent\n\n");
        md.push_str(&self.original_request);
        md.push('\n');

        if let Some(goal) = &self.interpreted_goal {
            md.push_str("\n## Interpreted Goal\n\n");
            md.push_str(goal);
            md.push('\n');
        }

        if let Some(summary) = &self.summary {
            md.push_str("\n## Summary\n\n");
            md.push_str(summary);
            md.push('\n');
        }

        if !self.dead_ends.is_empty() {
            md.push_str("\n## Dead Ends\n\n");
            for de in &self.dead_ends {
                md.push_str(&format!("- **{}**: {}\n", de.approach, de.reason));
            }
        }

        if !self.decisions.is_empty() {
            md.push_str("\n## Decisions\n\n");
            for d in &self.decisions {
                md.push_str(&format!("- **{}**: {}\n", d.description, d.rationale));
            }
        }

        md
    }

    /// Parse from Markdown
    pub fn from_markdown(md: &str) -> Result<Self, CoreError> {
        let mut original_request = String::new();
        let mut interpreted_goal = None;
        let mut summary = None;
        let mut dead_ends = Vec::new();
        let mut decisions = Vec::new();

        let mut current_section = "intent";
        let mut current_content = String::new();

        for line in md.lines() {
            if line.starts_with("# Intent") {
                current_section = "intent";
                current_content.clear();
                continue;
            } else if line.starts_with("## Interpreted Goal") {
                // Save previous section
                Self::save_section(
                    current_section,
                    &current_content,
                    &mut original_request,
                    &mut interpreted_goal,
                    &mut summary,
                );
                current_section = "goal";
                current_content.clear();
                continue;
            } else if line.starts_with("## Summary") {
                Self::save_section(
                    current_section,
                    &current_content,
                    &mut original_request,
                    &mut interpreted_goal,
                    &mut summary,
                );
                current_section = "summary";
                current_content.clear();
                continue;
            } else if line.starts_with("## Dead Ends") {
                Self::save_section(
                    current_section,
                    &current_content,
                    &mut original_request,
                    &mut interpreted_goal,
                    &mut summary,
                );
                current_section = "dead_ends";
                current_content.clear();
                continue;
            } else if line.starts_with("## Decisions") {
                Self::save_section(
                    current_section,
                    &current_content,
                    &mut original_request,
                    &mut interpreted_goal,
                    &mut summary,
                );
                current_section = "decisions";
                current_content.clear();
                continue;
            }

            match current_section {
                "dead_ends" => {
                    if let Some(entry) = line.strip_prefix("- **") {
                        if let Some((approach, reason)) = entry.split_once("**: ") {
                            dead_ends.push(DeadEnd {
                                approach: approach.to_string(),
                                reason: reason.to_string(),
                            });
                        }
                    }
                }
                "decisions" => {
                    if let Some(entry) = line.strip_prefix("- **") {
                        if let Some((desc, rationale)) = entry.split_once("**: ") {
                            decisions.push(Decision {
                                description: desc.to_string(),
                                rationale: rationale.to_string(),
                            });
                        }
                    }
                }
                _ => {
                    if !current_content.is_empty() || !line.is_empty() {
                        if !current_content.is_empty() {
                            current_content.push('\n');
                        }
                        current_content.push_str(line);
                    }
                }
            }
        }

        // Save last section
        Self::save_section(
            current_section,
            &current_content,
            &mut original_request,
            &mut interpreted_goal,
            &mut summary,
        );

        Ok(Intent {
            original_request,
            interpreted_goal,
            summary,
            dead_ends,
            decisions,
        })
    }

    fn save_section(
        section: &str,
        content: &str,
        original_request: &mut String,
        interpreted_goal: &mut Option<String>,
        summary: &mut Option<String>,
    ) {
        let trimmed = content.trim().to_string();
        if trimmed.is_empty() {
            return;
        }
        match section {
            "intent" => *original_request = trimmed,
            "goal" => *interpreted_goal = Some(trimmed),
            "summary" => *summary = Some(trimmed),
            _ => {}
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_markdown_roundtrip() {
        let intent = Intent {
            original_request: "Add OAuth2 authentication".into(),
            interpreted_goal: Some("Implement OAuth2 with PKCE for the SPA".into()),
            summary: Some("Implemented OAuth2 with custom middleware".into()),
            dead_ends: vec![
                DeadEnd {
                    approach: "passport.js".into(),
                    reason: "Middleware conflict with existing stack".into(),
                },
                DeadEnd {
                    approach: "Auth0 SDK".into(),
                    reason: "Added 2MB to bundle".into(),
                },
            ],
            decisions: vec![Decision {
                description: "Custom middleware".into(),
                rationale: "Full control over auth flow".into(),
            }],
        };

        let md = intent.to_markdown();
        let parsed = Intent::from_markdown(&md).unwrap();

        assert_eq!(intent.original_request, parsed.original_request);
        assert_eq!(intent.interpreted_goal, parsed.interpreted_goal);
        assert_eq!(intent.summary, parsed.summary);
        assert_eq!(intent.dead_ends.len(), parsed.dead_ends.len());
        assert_eq!(intent.dead_ends[0].approach, parsed.dead_ends[0].approach);
        assert_eq!(intent.decisions.len(), parsed.decisions.len());
    }

    #[test]
    fn test_minimal_intent() {
        let intent = Intent {
            original_request: "Fix the bug".into(),
            interpreted_goal: None,
            summary: None,
            dead_ends: vec![],
            decisions: vec![],
        };
        let md = intent.to_markdown();
        let parsed = Intent::from_markdown(&md).unwrap();
        assert_eq!(intent.original_request, parsed.original_request);
        assert!(parsed.interpreted_goal.is_none());
        assert!(parsed.dead_ends.is_empty());
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

use crate::error::CoreError;

/// A single line of the transcript.jsonl file.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct TranscriptEntry {
    pub timestamp: DateTime<Utc>,
    pub role: Role,
    pub content: TranscriptContent,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub token_count: Option<u64>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum Role {
    User,
    Assistant,
    System,
    Tool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type")]
pub enum TranscriptContent {
    #[serde(rename = "text")]
    Text { text: String },
    #[serde(rename = "tool_use")]
    ToolUse {
        tool_name: String,
        tool_id: String,
        input: serde_json::Value,
    },
    #[serde(rename = "tool_result")]
    ToolResult {
        tool_id: String,
        output: String,
        is_error: bool,
    },
    #[serde(rename = "thinking")]
    Thinking { text: String },
}

/// The full transcript, serialized as JSONL.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Transcript {
    pub entries: Vec<TranscriptEntry>,
}

impl Transcript {
    /// Serialize to JSONL bytes (one JSON object per line).
    pub fn to_jsonl(&self) -> Vec<u8> {
        let mut buf = Vec::new();
        for entry in &self.entries {
            if !buf.is_empty() {
                // entries after the first get a newline prefix
            }
            serde_json::to_writer(&mut buf, entry).expect("transcript entry serialization");
            buf.push(b'\n');
        }
        buf
    }

    /// Deserialize from JSONL bytes.
    pub fn from_jsonl(data: &[u8]) -> Result<Self, CoreError> {
        let text = std::str::from_utf8(data).map_err(|e| CoreError::Parse(e.to_string()))?;
        let mut entries = Vec::new();
        for line in text.lines() {
            if line.trim().is_empty() {
                continue;
            }
            let entry: TranscriptEntry =
                serde_json::from_str(line).map_err(CoreError::InvalidManifest)?;
            entries.push(entry);
        }
        Ok(Transcript { entries })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_entries() -> Vec<TranscriptEntry> {
        vec![
            TranscriptEntry {
                timestamp: Utc::now(),
                role: Role::User,
                content: TranscriptContent::Text {
                    text: "Add OAuth2 authentication".into(),
                },
                token_count: None,
            },
            TranscriptEntry {
                timestamp: Utc::now(),
                role: Role::Assistant,
                content: TranscriptContent::Thinking {
                    text: "Let me think about this...".into(),
                },
                token_count: Some(50),
            },
            TranscriptEntry {
                timestamp: Utc::now(),
                role: Role::Assistant,
                content: TranscriptContent::ToolUse {
                    tool_name: "Write".into(),
                    tool_id: "toolu_123".into(),
                    input: serde_json::json!({"path": "src/auth.rs"}),
                },
                token_count: Some(100),
            },
            TranscriptEntry {
                timestamp: Utc::now(),
                role: Role::Tool,
                content: TranscriptContent::ToolResult {
                    tool_id: "toolu_123".into(),
                    output: "File written successfully".into(),
                    is_error: false,
                },
                token_count: None,
            },
        ]
    }

    #[test]
    fn test_jsonl_roundtrip() {
        let transcript = Transcript {
            entries: sample_entries(),
        };
        let jsonl = transcript.to_jsonl();
        let parsed = Transcript::from_jsonl(&jsonl).unwrap();
        assert_eq!(transcript.entries.len(), parsed.entries.len());
        for (a, b) in transcript.entries.iter().zip(parsed.entries.iter()) {
            assert_eq!(a.role, b.role);
            assert_eq!(a.content, b.content);
            assert_eq!(a.token_count, b.token_count);
        }
    }

    #[test]
    fn test_empty_transcript() {
        let transcript = Transcript::default();
        let jsonl = transcript.to_jsonl();
        let parsed = Transcript::from_jsonl(&jsonl).unwrap();
        assert!(parsed.entries.is_empty());
    }

    #[test]
    fn test_content_variants_serde() {
        let text = TranscriptContent::Text {
            text: "hello".into(),
        };
        let json = serde_json::to_string(&text).unwrap();
        assert!(json.contains("\"type\":\"text\""));

        let tool_use = TranscriptContent::ToolUse {
            tool_name: "Bash".into(),
            tool_id: "id1".into(),
            input: serde_json::json!({"command": "ls"}),
        };
        let json = serde_json::to_string(&tool_use).unwrap();
        assert!(json.contains("\"type\":\"tool_use\""));
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

/// Structured list of all tool calls and file operations.
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct Operations {
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub tool_calls: Vec<ToolCall>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub file_changes: Vec<FileChange>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub shell_commands: Vec<ShellCommand>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ToolCall {
    pub timestamp: DateTime<Utc>,
    pub tool_name: String,
    pub input: serde_json::Value,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub output_summary: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub duration_ms: Option<u64>,
    #[serde(default)]
    pub is_error: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct FileChange {
    pub path: String,
    pub change_type: FileChangeType,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lines_added: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lines_removed: Option<u32>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum FileChangeType {
    Created,
    Modified,
    Deleted,
    Renamed { from: String },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ShellCommand {
    pub timestamp: DateTime<Utc>,
    pub command: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub exit_code: Option<i32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub duration_ms: Option<u64>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_operations_serde_roundtrip() {
        let ops = Operations {
            tool_calls: vec![ToolCall {
                timestamp: Utc::now(),
                tool_name: "Write".into(),
                input: serde_json::json!({"path": "src/auth.rs"}),
                output_summary: Some("File created".into()),
                duration_ms: Some(150),
                is_error: false,
            }],
            file_changes: vec![FileChange {
                path: "src/auth.rs".into(),
                change_type: FileChangeType::Created,
                lines_added: Some(50),
                lines_removed: None,
            }],
            shell_commands: vec![ShellCommand {
                timestamp: Utc::now(),
                command: "cargo test".into(),
                exit_code: Some(0),
                duration_ms: Some(3000),
            }],
        };
        let json = serde_json::to_string_pretty(&ops).unwrap();
        let parsed: Operations = serde_json::from_str(&json).unwrap();
        assert_eq!(ops, parsed);
    }

    #[test]
    fn test_rename_variant() {
        let change = FileChange {
            path: "src/new_auth.rs".into(),
            change_type: FileChangeType::Renamed {
                from: "src/auth.rs".into(),
            },
            lines_added: None,
            lines_removed: None,
        };
        let json = serde_json::to_string(&change).unwrap();
        assert!(json.contains("renamed"));
        let parsed: FileChange = serde_json::from_str(&json).unwrap();
        assert_eq!(change, parsed);
    }
}

use serde::{Deserialize, Serialize};

use super::engram::EngramId;

/// Relationships between this engram and other entities.
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct Lineage {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub parent_engram: Option<EngramId>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub child_engrams: Vec<EngramId>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub related_engrams: Vec<Relationship>,
    #[serde(default)]
    pub git_commits: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub branch: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Relationship {
    pub engram_id: EngramId,
    pub relation_type: RelationType,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum RelationType {
    FollowsFrom,
    Motivates,
    DependsOn,
    Supersedes,
    ConflictsWith,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_lineage_serde_roundtrip() {
        let lineage = Lineage {
            parent_engram: Some(EngramId("parent123".into())),
            child_engrams: vec![EngramId("child456".into())],
            related_engrams: vec![Relationship {
                engram_id: EngramId("related789".into()),
                relation_type: RelationType::FollowsFrom,
                description: Some("Previous auth attempt".into()),
            }],
            git_commits: vec!["abc123".into(), "def456".into()],
            branch: Some("feature/auth".into()),
        };
        let json = serde_json::to_string_pretty(&lineage).unwrap();
        let parsed: Lineage = serde_json::from_str(&json).unwrap();
        assert_eq!(lineage, parsed);
    }

    #[test]
