use std::collections::HashMap;
use std::path::{Path, PathBuf};

use sha2::{Digest, Sha256};
use walkdir::WalkDir;

use engram_core::model::{FileChange, FileChangeType};

/// Snapshot the working tree: map of relative path -> SHA256 hash.
/// Ignores .git directory and common build artifacts.
pub fn snapshot_working_tree(repo_root: &Path) -> Result<HashMap<PathBuf, Vec<u8>>, std::io::Error> {
    let mut snapshot = HashMap::new();

    for entry in WalkDir::new(repo_root)
        .into_iter()
        .filter_entry(|e| !is_ignored(e.path(), repo_root))
    {
        let entry = entry?;
        if !entry.file_type().is_file() {
            continue;
        }
        let rel_path = entry
            .path()
            .strip_prefix(repo_root)
            .unwrap_or(entry.path())
            .to_path_buf();

        match std::fs::read(entry.path()) {
            Ok(contents) => {
                let hash = Sha256::digest(&contents).to_vec();
                snapshot.insert(rel_path, hash);
            }
            Err(e) => {
                tracing::debug!("Skipping unreadable file {:?}: {}", entry.path(), e);
            }
        }
    }

    Ok(snapshot)
}

/// Compare before/after snapshots to detect file changes.
pub fn detect_changes(
    before: &HashMap<PathBuf, Vec<u8>>,
    after: &HashMap<PathBuf, Vec<u8>>,
) -> Vec<FileChange> {
    let mut changes = Vec::new();

    // Check for created and modified files
    for (path, after_hash) in after {
        match before.get(path) {
            None => {
                changes.push(FileChange {
                    path: path.to_string_lossy().to_string(),
                    change_type: FileChangeType::Created,
                    lines_added: None,
                    lines_removed: None,
                });
            }
            Some(before_hash) if before_hash != after_hash => {
                changes.push(FileChange {
                    path: path.to_string_lossy().to_string(),
                    change_type: FileChangeType::Modified,
                    lines_added: None,
                    lines_removed: None,
                });
            }
            _ => {} // Unchanged
        }
    }

    // Check for deleted files
    for path in before.keys() {
        if !after.contains_key(path) {
            changes.push(FileChange {
                path: path.to_string_lossy().to_string(),
                change_type: FileChangeType::Deleted,
                lines_added: None,
                lines_removed: None,
            });
        }
    }

    // Sort for deterministic output
    changes.sort_by(|a, b| a.path.cmp(&b.path));
    changes
}

fn is_ignored(path: &Path, root: &Path) -> bool {
    let rel = path.strip_prefix(root).unwrap_or(path);
    let name = rel
        .file_name()
        .map(|n| n.to_string_lossy())
        .unwrap_or_default();

    // Skip .git, target, node_modules, and other common build dirs
    matches!(
        name.as_ref(),
        ".git" | "target" | "node_modules" | ".DS_Store" | "__pycache__"
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn test_snapshot_and_detect_changes() {
        let tmp = TempDir::new().unwrap();
        let root = tmp.path();

        // Create initial files
        std::fs::write(root.join("existing.txt"), "hello").unwrap();
        std::fs::write(root.join("to_delete.txt"), "goodbye").unwrap();
        std::fs::write(root.join("unchanged.txt"), "same").unwrap();

        let before = snapshot_working_tree(root).unwrap();
        assert_eq!(before.len(), 3);

        // Make changes
        std::fs::write(root.join("existing.txt"), "modified").unwrap();
        std::fs::remove_file(root.join("to_delete.txt")).unwrap();
        std::fs::write(root.join("new_file.txt"), "new").unwrap();

        let after = snapshot_working_tree(root).unwrap();
        let changes = detect_changes(&before, &after);

        assert_eq!(changes.len(), 3);

        let created: Vec<_> = changes
            .iter()
            .filter(|c| matches!(c.change_type, FileChangeType::Created))
            .collect();
        assert_eq!(created.len(), 1);
        assert_eq!(created[0].path, "new_file.txt");

        let modified: Vec<_> = changes
            .iter()
            .filter(|c| matches!(c.change_type, FileChangeType::Modified))
            .collect();
        assert_eq!(modified.len(), 1);
        assert_eq!(modified[0].path, "existing.txt");

        let deleted: Vec<_> = changes
            .iter()
            .filter(|c| matches!(c.change_type, FileChangeType::Deleted))
            .collect();
        assert_eq!(deleted.len(), 1);
        assert_eq!(deleted[0].path, "to_delete.txt");
    }

    #[test]
    fn test_ignores_git_dir() {
        let tmp = TempDir::new().unwrap();
        let root = tmp.path();

        std::fs::create_dir_all(root.join(".git/objects")).unwrap();
        std::fs::write(root.join(".git/HEAD"), "ref: refs/heads/main").unwrap();
        std::fs::write(root.join("real_file.txt"), "content").unwrap();

        let snapshot = snapshot_working_tree(root).unwrap();
        assert_eq!(snapshot.len(), 1);
        assert!(snapshot.contains_key(Path::new("real_file.txt")));
    }
}

use std::collections::HashMap;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use chrono::{DateTime, Utc};
use portable_pty::{native_pty_system, CommandBuilder, PtySize};

use engram_core::model::FileChange;

use crate::error::CaptureError;

use super::detector::{detect_changes, snapshot_working_tree};

/// Configuration for a PTY-wrapped agent session.
#[derive(Debug, Clone)]
pub struct PtyWrapperConfig {
    pub command: String,
    pub args: Vec<String>,
    pub working_dir: PathBuf,
    pub agent_name: Option<String>,
}

/// Result of a captured PTY session.
#[derive(Debug, Clone)]
pub struct CapturedSession {
    pub raw_output: Vec<u8>,
    pub start_time: DateTime<Utc>,
    pub end_time: DateTime<Utc>,
    pub exit_code: Option<u32>,
    pub file_changes: Vec<FileChange>,
    pub command: String,
    pub args: Vec<String>,
}

/// A PTY session that captures agent output and detects file changes.
pub struct PtySession {
    config: PtyWrapperConfig,
    file_snapshot_before: HashMap<PathBuf, Vec<u8>>,
    start_time: DateTime<Utc>,
}

impl PtySession {
    /// Start a new PTY session: snapshot the working tree.
    pub fn start(config: PtyWrapperConfig) -> Result<Self, CaptureError> {
        let snapshot = snapshot_working_tree(&config.working_dir)
            .map_err(|e| CaptureError::Pty(format!("Failed to snapshot working tree: {e}")))?;

        Ok(Self {
            config,
            file_snapshot_before: snapshot,
            start_time: Utc::now(),
        })
    }

    /// Run the session to completion. Spawns the command in a PTY,
    /// passes stdin/stdout through, captures output.
    pub fn run(self) -> Result<CapturedSession, CaptureError> {
        let pty_system = native_pty_system();

        // Get terminal size from current terminal, fall back to defaults
        let (cols, rows) = terminal_size().unwrap_or((80, 24));

        let pair = pty_system
            .openpty(PtySize {
                rows,
                cols,
                pixel_width: 0,
                pixel_height: 0,
            })
            .map_err(|e| CaptureError::Pty(format!("Failed to open PTY: {e}")))?;

        // Build the command
        let mut cmd = CommandBuilder::new(&self.config.command);
        cmd.args(&self.config.args);
        cmd.cwd(&self.config.working_dir);

        // Spawn the child process
        let mut child = pair
            .slave
            .spawn_command(cmd)
            .map_err(|e| CaptureError::Pty(format!("Failed to spawn command: {e}")))?;

        // Drop the slave to avoid hanging
        drop(pair.slave);

        // Set up capture buffer
        let capture_buffer = Arc::new(Mutex::new(Vec::new()));

        // Get reader/writer from master
        let mut reader = pair
            .master
            .try_clone_reader()
            .map_err(|e| CaptureError::Pty(format!("Failed to clone PTY reader: {e}")))?;
        let mut writer = pair
            .master
            .take_writer()
            .map_err(|e| CaptureError::Pty(format!("Failed to take PTY writer: {e}")))?;

        // Reader thread: PTY output -> stdout + capture buffer
        let buf_clone = Arc::clone(&capture_buffer);
        let reader_handle = std::thread::spawn(move || {
            let mut buf = [0u8; 4096];
            loop {
                match reader.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        // Pass through to stdout
                        let _ = std::io::stdout().write_all(&buf[..n]);
                        let _ = std::io::stdout().flush();
                        // Capture
                        if let Ok(mut capture) = buf_clone.lock() {
                            capture.extend_from_slice(&buf[..n]);
                        }
                    }
                    Err(_) => break,
                }
            }
        });

        // Writer thread: stdin -> PTY
        let writer_handle = std::thread::spawn(move || {
            let mut buf = [0u8; 4096];
            loop {
                match std::io::stdin().read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        if writer.write_all(&buf[..n]).is_err() {
                            break;
                        }
                    }
                    Err(_) => break,
                }
            }
        });

        // Wait for child to exit
        let status = child
            .wait()
            .map_err(|e| CaptureError::Pty(format!("Failed to wait for child: {e}")))?;

        // Wait for reader to finish (writer may hang on stdin, so don't join it)
        let _ = reader_handle.join();
        drop(writer_handle); // Don't wait for stdin thread

        let end_time = Utc::now();
        let exit_code = status.exit_code();

        // Detect file changes
        let snapshot_after = snapshot_working_tree(&self.config.working_dir)
            .map_err(|e| CaptureError::Pty(format!("Failed to snapshot working tree: {e}")))?;
        let file_changes = detect_changes(&self.file_snapshot_before, &snapshot_after);

        // Collect captured output
        let raw_output = capture_buffer
            .lock()
            .map(|buf| buf.clone())
            .unwrap_or_default();

        Ok(CapturedSession {
            raw_output,
            start_time: self.start_time,
            end_time,
            exit_code,
            file_changes,
            command: self.config.command,
            args: self.config.args,
        })
    }
}

/// Try to get the current terminal size.
fn terminal_size() -> Option<(u16, u16)> {
    // Use a simple ioctl-based approach on Unix
    #[cfg(unix)]
    {
        use std::mem::MaybeUninit;

        #[repr(C)]
        struct Winsize {
            ws_row: u16,
            ws_col: u16,
            ws_xpixel: u16,
            ws_ypixel: u16,
        }

        let mut ws = MaybeUninit::<Winsize>::uninit();
        // SAFETY: ioctl with TIOCGWINSZ is safe to call with a Winsize pointer on stdout fd
        let ret =
            unsafe { libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, ws.as_mut_ptr()) };
        if ret == 0 {
            // SAFETY: ioctl returned success, so ws is initialized
            let ws = unsafe { ws.assume_init() };
            if ws.ws_col > 0 && ws.ws_row > 0 {
                return Some((ws.ws_col, ws.ws_row));
            }
        }
        None
    }

    #[cfg(not(unix))]
    {
        None
    }
}

use chrono::Utc;

use engram_core::model::*;
use engram_core::storage::GitStorage;

use crate::error::CaptureError;
use crate::pty::CapturedSession;

/// Builds an EngramData from a CapturedSession.
pub struct SessionBuilder {
    agent_info: AgentInfo,
    captured: CapturedSession,
    git_commits: Vec<String>,
    parent_engram: Option<EngramId>,
}

impl SessionBuilder {
    pub fn new(agent_info: AgentInfo, captured: CapturedSession) -> Self {
        Self {
            agent_info,
            captured,
            git_commits: Vec::new(),
            parent_engram: None,
        }
    }

    /// Set the git commits produced during this session.
    pub fn with_commits(mut self, commits: Vec<String>) -> Self {
        self.git_commits = commits;
        self
    }

    /// Set the parent engram (for chaining).
    pub fn with_parent(mut self, parent: EngramId) -> Self {
        self.parent_engram = Some(parent);
        self
    }

    /// Build the EngramData.
    pub fn build(self) -> EngramData {
        let id = EngramId::new();

        // Extract intent from the command + args
        let original_request = if self.captured.args.is_empty() {
            self.captured.command.clone()
        } else {
            format!("{} {}", self.captured.command, self.captured.args.join(" "))
        };

        let summary = if self.captured.file_changes.is_empty() {
            Some(format!(
                "Ran {} (exit code: {})",
                self.captured.command,
                self.captured
                    .exit_code
                    .map(|c| c.to_string())
                    .unwrap_or_else(|| "unknown".into())
            ))
        } else {
            Some(format!(
                "{} file(s) changed by {}",
                self.captured.file_changes.len(),
                self.captured.command
            ))
        };

        let manifest = Manifest {
            id,
            version: 1,
            created_at: self.captured.start_time,
            finished_at: Some(self.captured.end_time),
            agent: self.agent_info,
            git_commits: self.git_commits.clone(),
            token_usage: TokenUsage::default(), // PTY capture doesn't know token usage
            summary,
            tags: Vec::new(),
            capture_mode: CaptureMode::Wrapper,
        };

        let intent = Intent {
            original_request,
            interpreted_goal: None,
            summary: manifest.summary.clone(),
            dead_ends: Vec::new(),
            decisions: Vec::new(),
        };

        // Build transcript from raw output
        let transcript = Transcript {
            entries: vec![TranscriptEntry {
                timestamp: self.captured.start_time,
                role: Role::System,
                content: TranscriptContent::Text {
                    text: format!(
                        "PTY session: {} {}",
                        self.captured.command,
                        self.captured.args.join(" ")
                    ),
                },
                token_count: None,
            }],
        };

        let operations = Operations {
            tool_calls: Vec::new(),
            file_changes: self.captured.file_changes.clone(),
            shell_commands: vec![ShellCommand {
                timestamp: self.captured.start_time,
                command: format!(
                    "{} {}",
                    self.captured.command,
                    self.captured.args.join(" ")
                ),
                exit_code: self.captured.exit_code.map(|c| c as i32),
                duration_ms: Some(
                    (self.captured.end_time - self.captured.start_time).num_milliseconds() as u64,
                ),
            }],
        };

        let lineage = Lineage {
            parent_engram: self.parent_engram,
            git_commits: self.git_commits,
            branch: None, // Could detect from git HEAD
            ..Default::default()
        };

        EngramData {
            manifest,
            intent,
            transcript,
            operations,
            lineage,
        }
    }

    /// Build and immediately store in Git.
    pub fn build_and_store(self, storage: &GitStorage) -> Result<EngramId, CaptureError> {
        let data = self.build();
        let id = storage.create(&data)?;
        Ok(id)
    }
}

