use anyhow::{Context, Result};
use clap::Args;

use engram_capture::pty::{PtySession, PtyWrapperConfig};
use engram_capture::session::SessionBuilder;
use engram_core::model::AgentInfo;
use engram_core::storage::GitStorage;

#[derive(Args)]
pub struct RecordArgs {
    /// Agent name (auto-detected from command if not specified)
    #[arg(long)]
    pub agent: Option<String>,

    /// Command and arguments to run (after --)
    #[arg(trailing_var_arg = true, required = true)]
    pub command: Vec<String>,
}

pub fn run(args: &RecordArgs) -> Result<()> {
    let storage = GitStorage::discover().context("Not inside a Git repository")?;

    if !storage.is_initialized() {
        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
    }

    if args.command.is_empty() {
        anyhow::bail!("No command specified. Usage: engram record -- <command> [args...]");
    }

    let cmd = &args.command[0];
    let cmd_args = &args.command[1..];
    let agent_name = args
        .agent
        .clone()
        .unwrap_or_else(|| detect_agent_name(cmd));

    let working_dir = std::env::current_dir().context("Failed to get current directory")?;

    eprintln!(
        "Recording session: {} {} (agent: {})",
        cmd,
        cmd_args.join(" "),
        agent_name
    );

    let config = PtyWrapperConfig {
        command: cmd.clone(),
        args: cmd_args.to_vec(),
        working_dir,
        agent_name: Some(agent_name.clone()),
    };

    let session = PtySession::start(config).context("Failed to start PTY session")?;
    let captured = session.run().context("PTY session failed")?;

    let exit_code = captured.exit_code;
    let file_count = captured.file_changes.len();
    let duration = captured.end_time - captured.start_time;

    let agent_info = AgentInfo {
        name: agent_name,
        model: None,
        version: None,
    };

    let id = SessionBuilder::new(agent_info, captured)
        .build_and_store(&storage)
        .context("Failed to store engram")?;

    eprintln!();
    eprintln!("Engram {} captured:", &id.as_str()[..8]);
    eprintln!(
        "  Exit code: {}",
        exit_code
            .map(|c| c.to_string())
            .unwrap_or_else(|| "unknown".into())
    );
    eprintln!("  Duration:  {:.1}s", duration.num_milliseconds() as f64 / 1000.0);
    eprintln!("  Files changed: {file_count}");
    eprintln!();
    eprintln!("View with: engram show {}", &id.as_str()[..8]);

    Ok(())
}

fn detect_agent_name(cmd: &str) -> String {
    let basename = std::path::Path::new(cmd)
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| cmd.to_string());

    match basename.as_str() {
        "claude" | "claude-code" => "claude-code".into(),
        "aider" => "aider".into(),
        "cursor" | "cursor-cli" => "cursor".into(),
        "copilot" => "copilot".into(),
        _ => basename,
    }
}

use std::path::PathBuf;

use anyhow::{Context, Result};
use clap::{Args, ValueEnum};

use engram_capture::import::aider::AiderImporter;
use engram_capture::import::claude_code::ClaudeCodeImporter;
use engram_capture::import::detect::detect_sources;
use engram_core::storage::GitStorage;

#[derive(Args)]
pub struct ImportArgs {
    /// Path to session file or directory
    pub path: Option<PathBuf>,

    /// Format hint
    #[arg(long, value_enum)]
    pub format: Option<ImportFormat>,

    /// Auto-detect and import all discoverable sessions
    #[arg(long)]
    pub auto_detect: bool,

    /// Only show what would be imported (dry run)
    #[arg(long)]
    pub dry_run: bool,
}

#[derive(Clone, ValueEnum)]
pub enum ImportFormat {
    ClaudeCode,
    Aider,
}

pub fn run(args: &ImportArgs) -> Result<()> {
    let storage = GitStorage::discover().context("Not inside a Git repository")?;

    if !storage.is_initialized() {
        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
    }

    if args.auto_detect {
        return run_auto_detect(&storage, args.dry_run);
    }

    let path = args
        .path
        .as_ref()
        .ok_or_else(|| anyhow::anyhow!("Specify a path or use --auto-detect"))?;

    let format = args.format.as_ref().ok_or_else(|| {
        anyhow::anyhow!("Specify --format (claude-code or aider) or use --auto-detect")
    })?;

    match format {
        ImportFormat::ClaudeCode => {
            println!("Importing Claude Code session: {}", path.display());
            if args.dry_run {
                println!("  (dry run - no changes made)");
                return Ok(());
            }
            let data = ClaudeCodeImporter::import_session(path)
                .context("Failed to parse Claude Code session")?;
            let tokens = data.manifest.token_usage.total_tokens;
            let entries = data.transcript.entries.len();
            let id = storage.create(&data).context("Failed to store engram")?;
            println!(
                "  Imported engram {} ({} transcript entries, {} tokens)",
                &id.as_str()[..8],
                entries,
                tokens
            );
        }
        ImportFormat::Aider => {
            println!("Importing Aider history: {}", path.display());
            if args.dry_run {
                println!("  (dry run - no changes made)");
                return Ok(());
            }
            let engrams =
                AiderImporter::import_history(path).context("Failed to parse Aider history")?;
            for data in engrams {
                let entries = data.transcript.entries.len();
                let id = storage.create(&data).context("Failed to store engram")?;
                println!(
                    "  Imported engram {} ({} transcript entries)",
                    &id.as_str()[..8],
                    entries
                );
            }
        }
    }

    Ok(())
}

fn run_auto_detect(storage: &GitStorage, dry_run: bool) -> Result<()> {
    let workdir = storage
        .workdir()
        .ok_or_else(|| anyhow::anyhow!("Cannot determine working directory"))?;

    let sources = detect_sources(workdir).context("Failed to detect import sources")?;

    if sources.is_empty() {
        println!("No importable sessions found.");
        println!();
        println!("Looked for:");
        println!("  - Claude Code sessions in ~/.claude/projects/");
        println!("  - Aider history in .aider.chat.history.md");
        return Ok(());
    }

    println!("Found {} importable source(s):", sources.len());
    for source in &sources {
        println!("  - {}", source.description());
    }

    if dry_run {
        println!();
        println!("(dry run - no changes made)");
        return Ok(());
    }

    println!();
    let mut total_imported = 0;

    for source in &sources {
        match source {
            engram_capture::import::detect::ImportSource::ClaudeCode { session_path } => {
                match ClaudeCodeImporter::import_session(session_path) {
                    Ok(data) => {
                        let entries = data.transcript.entries.len();
                        let tokens = data.manifest.token_usage.total_tokens;
                        match storage.create(&data) {
                            Ok(id) => {
                                println!(
                                    "  Imported {} ({} entries, {} tokens)",
                                    &id.as_str()[..8],
                                    entries,
                                    tokens,
                                );
                                total_imported += 1;
                            }
                            Err(e) => {
                                eprintln!("  Error storing {}: {e}", session_path.display());
                            }
                        }
                    }
                    Err(e) => {
                        eprintln!("  Error importing {}: {e}", session_path.display());
                    }
                }
            }
            engram_capture::import::detect::ImportSource::Aider { history_path } => {
                match AiderImporter::import_history(history_path) {
                    Ok(engrams) => {
                        for data in engrams {
                            let entries = data.transcript.entries.len();
                            match storage.create(&data) {
                                Ok(id) => {
                                    println!(
                                        "  Imported {} ({} entries)",
                                        &id.as_str()[..8],
                                        entries,
                                    );
                                    total_imported += 1;
                                }
                                Err(e) => {
                                    eprintln!("  Error storing aider session: {e}");
                                }
                            }
                        }
                    }
                    Err(e) => {
                        eprintln!("  Error importing {}: {e}", history_path.display());
                    }
                }
            }
        }
    }

    println!();
    println!("Imported {total_imported} engram(s).");

    Ok(())
}

