use engram_core::error::CoreError;

#[derive(Debug, thiserror::Error)]
pub enum QueryError {
    #[error("Index error: {0}")]
    Index(String),

    #[error("Search error: {0}")]
    Search(String),

    #[error("Core error: {0}")]
    Core(#[from] CoreError),

    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    #[error("Serialization error: {0}")]
    Serde(#[from] serde_json::Error),
}

impl From<tantivy::TantivyError> for QueryError {
    fn from(e: tantivy::TantivyError) -> Self {
        QueryError::Index(e.to_string())
    }
}

use tantivy::schema::*;

/// Holds field handles for the engram Tantivy schema.
pub struct EngramSchema {
    pub schema: Schema,
    pub id: Field,
    pub intent_request: Field,
    pub intent_summary: Field,
    pub transcript_text: Field,
    pub agent_name: Field,
    pub agent_model: Field,
    pub created_at: Field,
    pub file_paths: Field,
    pub dead_ends: Field,
    pub cost_usd: Field,
    pub total_tokens: Field,
    pub manifest_json: Field,
}

impl EngramSchema {
    pub fn new() -> Self {
        let mut builder = Schema::builder();

        let id = builder.add_text_field("id", STRING | STORED);
        let intent_request = builder.add_text_field("intent_request", TEXT | STORED);
        let intent_summary = builder.add_text_field("intent_summary", TEXT | STORED);
        let transcript_text = builder.add_text_field("transcript_text", TEXT);
        let agent_name = builder.add_text_field("agent_name", STRING | STORED);
        let agent_model = builder.add_text_field("agent_model", STRING | STORED);
        let created_at = builder.add_date_field("created_at", INDEXED | STORED);
        let file_paths = builder.add_text_field("file_paths", TEXT | STORED);
        let dead_ends = builder.add_text_field("dead_ends", TEXT | STORED);
        let cost_usd = builder.add_f64_field("cost_usd", INDEXED | STORED);
        let total_tokens = builder.add_u64_field("total_tokens", INDEXED | STORED);
        let manifest_json = builder.add_text_field("manifest_json", STORED);

        let schema = builder.build();

        Self {
            schema,
            id,
            intent_request,
            intent_summary,
            transcript_text,
            agent_name,
            agent_model,
            created_at,
            file_paths,
            dead_ends,
            cost_usd,
            total_tokens,
            manifest_json,
        }
    }
}

impl Default for EngramSchema {
    fn default() -> Self {
        Self::new()
    }
}

use std::path::Path;

use tantivy::doc;
use tantivy::schema::Value;
use tantivy::{Index, IndexWriter};

use engram_core::model::{EngramData, TranscriptContent};

use super::schema::EngramSchema;
use crate::error::QueryError;

/// Writes engrams to the Tantivy index.
pub struct EngramIndexWriter {
    schema: EngramSchema,
    index: Index,
    writer: IndexWriter,
}

impl EngramIndexWriter {
    /// Open or create an index at the given path.
    pub fn open(path: &Path) -> Result<Self, QueryError> {
        let schema = EngramSchema::new();
        let index = if path.exists() && path.join("meta.json").exists() {
            Index::open_in_dir(path)?
        } else {
            std::fs::create_dir_all(path).map_err(QueryError::Io)?;
            Index::create_in_dir(path, schema.schema.clone())?
        };

        // 50MB heap for indexing
        let writer = index.writer(50_000_000)?;

        Ok(Self {
            schema,
            index,
            writer,
        })
    }

    /// Index a single engram.
    pub fn index_engram(&mut self, data: &EngramData) -> Result<(), QueryError> {
        let s = &self.schema;

        // Concatenate transcript text entries
        let transcript_text: String = data
            .transcript
            .entries
            .iter()
            .filter_map(|e| match &e.content {
                TranscriptContent::Text { text } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("\n");

        // Concatenate file paths
        let file_paths: String = data
            .operations
            .file_changes
            .iter()
            .map(|fc| fc.path.clone())
            .collect::<Vec<_>>()
            .join("\n");

        // Concatenate dead ends
        let dead_ends: String = data
            .intent
            .dead_ends
            .iter()
            .map(|de| format!("{}: {}", de.approach, de.reason))
            .collect::<Vec<_>>()
            .join("\n");

        // Convert chrono to tantivy datetime
        let created_at = tantivy::DateTime::from_timestamp_secs(
            data.manifest.created_at.timestamp(),
        );

        let manifest_json = serde_json::to_string(&data.manifest)?;

        self.writer.add_document(doc!(
            s.id => data.manifest.id.as_str(),
            s.intent_request => data.intent.original_request.as_str(),
            s.intent_summary => data.intent.summary.as_deref().unwrap_or(""),
            s.transcript_text => transcript_text,
            s.agent_name => data.manifest.agent.name.as_str(),
            s.agent_model => data.manifest.agent.model.as_deref().unwrap_or(""),
            s.created_at => created_at,
            s.file_paths => file_paths,
            s.dead_ends => dead_ends,
            s.cost_usd => data.manifest.token_usage.cost_usd.unwrap_or(0.0),
            s.total_tokens => data.manifest.token_usage.total_tokens,
            s.manifest_json => manifest_json,
        ))?;

        Ok(())
    }

    /// Commit all pending changes.
    pub fn commit(&mut self) -> Result<(), QueryError> {
        self.writer.commit()?;
        Ok(())
    }

    /// Delete an engram from the index by its ID.
    pub fn delete_engram(&mut self, id: &str) -> Result<(), QueryError> {
        let term = tantivy::Term::from_field_text(self.schema.id, id);
        self.writer.delete_term(term);
        Ok(())
    }

    /// Get a reference to the underlying index.
    pub fn index(&self) -> &Index {
        &self.index
    }
}

use std::path::Path;

use tantivy::collector::TopDocs;
use tantivy::query::QueryParser;
use tantivy::schema::Value;
use tantivy::{Index, ReloadPolicy};

use engram_core::model::Manifest;

use super::schema::EngramSchema;
use crate::error::QueryError;

/// Result of a search query.
#[derive(Debug, Clone)]
pub struct SearchResult {
    pub manifest: Manifest,
    pub score: f32,
    pub snippet: Option<String>,
}

/// Searches the engram index.
pub struct EngramSearcher {
    schema: EngramSchema,
    index: Index,
}

impl EngramSearcher {
    /// Open an existing index for reading.
    pub fn open(path: &Path) -> Result<Self, QueryError> {
        let schema = EngramSchema::new();
        let index = Index::open_in_dir(path)?;
        Ok(Self { schema, index })
    }

    /// Search engrams with a free-text query.
    pub fn search(&self, query_str: &str, limit: usize) -> Result<Vec<SearchResult>, QueryError> {
        let reader = self
            .index
            .reader_builder()
            .reload_policy(ReloadPolicy::OnCommitWithDelay)
            .try_into()?;
        let searcher = reader.searcher();

        let query_parser = QueryParser::for_index(
            &self.index,
            vec![
                self.schema.intent_request,
                self.schema.intent_summary,
                self.schema.transcript_text,
                self.schema.dead_ends,
                self.schema.file_paths,
            ],
        );

        let query = query_parser
            .parse_query(query_str)
            .map_err(|e| QueryError::Search(e.to_string()))?;

        let top_docs = searcher.search(&query, &TopDocs::with_limit(limit))?;

        let mut results = Vec::with_capacity(top_docs.len());
        for (score, doc_address) in top_docs {
            let doc: tantivy::TantivyDocument = searcher.doc(doc_address)?;

            // Extract manifest JSON
            let manifest_json = doc
                .get_first(self.schema.manifest_json)
                .and_then(|v| v.as_str())
                .unwrap_or("{}");

            let manifest: Manifest = serde_json::from_str(manifest_json)?;

            // Extract snippet from intent summary
            let snippet = doc
                .get_first(self.schema.intent_summary)
                .and_then(|v| v.as_str())
                .map(|s| s.to_string());

            results.push(SearchResult {
                manifest,
                score,
                snippet,
            });
        }

        Ok(results)
    }

    /// Search for engrams that modified a specific file path.
    pub fn search_by_file(
        &self,
        file_path: &str,
        limit: usize,
    ) -> Result<Vec<SearchResult>, QueryError> {
        let reader = self
            .index
            .reader_builder()
            .reload_policy(ReloadPolicy::OnCommitWithDelay)
            .try_into()?;
        let searcher = reader.searcher();

        let query_parser =
            QueryParser::for_index(&self.index, vec![self.schema.file_paths]);

        let query = query_parser
            .parse_query(file_path)
            .map_err(|e| QueryError::Search(e.to_string()))?;

        let top_docs = searcher.search(&query, &TopDocs::with_limit(limit))?;

        let mut results = Vec::with_capacity(top_docs.len());
        for (score, doc_address) in top_docs {
            let doc: tantivy::TantivyDocument = searcher.doc(doc_address)?;
            let manifest_json = doc
                .get_first(self.schema.manifest_json)
                .and_then(|v| v.as_str())
                .unwrap_or("{}");
            let manifest: Manifest = serde_json::from_str(manifest_json)?;

            let snippet = doc
                .get_first(self.schema.intent_summary)
                .and_then(|v| v.as_str())
                .map(|s| s.to_string());

            results.push(SearchResult {
                manifest,
                score,
                snippet,
            });
        }

        Ok(results)
    }
}

use std::path::Path;

use engram_core::storage::GitStorage;

use super::writer::EngramIndexWriter;
use crate::error::QueryError;

/// Rebuild the index from scratch by reading all engrams from Git.
pub fn rebuild_index(storage: &GitStorage, index_path: &Path) -> Result<usize, QueryError> {
    // Remove existing index
    if index_path.exists() {
        std::fs::remove_dir_all(index_path).map_err(QueryError::Io)?;
    }

    let mut writer = EngramIndexWriter::open(index_path)?;
    let manifests = storage.list(&Default::default())?;

    let mut count = 0;
    for manifest in &manifests {
        match storage.read(&manifest.id) {
            Ok(data) => {
                writer.index_engram(&data)?;
                count += 1;
            }
            Err(e) => {
                tracing::warn!("Failed to read engram {}: {e}", manifest.id);
            }
        }
    }

    writer.commit()?;

    tracing::info!("Indexed {count} engrams");
    Ok(count)
}

