use crate::index::{rebuild_index, EngramIndexWriter, EngramSearcher, SearchResult};

/// High-level search engine that manages index lifecycle.
pub struct SearchEngine {
    index_path: PathBuf,
}

impl SearchEngine {
    /// Open a search engine for a repository. Index is stored at `.git/engram-index/`.
    pub fn open(storage: &GitStorage) -> Result<Self, QueryError> {
        let git_dir = storage.git_dir();
        let index_path = git_dir.join("engram-index");
        Ok(Self { index_path })
    }

    /// Ensure the index exists, creating it if needed.
    pub fn ensure_index(&self, storage: &GitStorage) -> Result<(), QueryError> {
        if !self.index_path.exists() || !self.index_path.join("meta.json").exists() {
            rebuild_index(storage, &self.index_path)?;
        }
        Ok(())
    }

    /// Search engrams by free-text query.
    pub fn search(
        &self,
        storage: &GitStorage,
        query: &str,
        limit: usize,
    ) -> Result<Vec<SearchResult>, QueryError> {
        self.ensure_index(storage)?;
        let searcher = EngramSearcher::open(&self.index_path)?;
        searcher.search(query, limit)
    }

    /// Search for engrams that touched a file.
    pub fn search_by_file(
        &self,
        storage: &GitStorage,
        file_path: &str,
        limit: usize,
    ) -> Result<Vec<SearchResult>, QueryError> {
        self.ensure_index(storage)?;
        let searcher = EngramSearcher::open(&self.index_path)?;
        searcher.search_by_file(file_path, limit)
    }

    /// Index a single new engram (incremental update).
    pub fn index_engram(&self, data: &EngramData) -> Result<(), QueryError> {
        if !self.index_path.exists() {
            return Ok(()); // Index doesn't exist yet, skip
        }
        let mut writer = EngramIndexWriter::open(&self.index_path)?;
        writer.index_engram(data)?;
        writer.commit()?;
        Ok(())
    }

    /// Rebuild the index from scratch.
    pub fn rebuild(&self, storage: &GitStorage) -> Result<usize, QueryError> {
        rebuild_index(storage, &self.index_path)
    }

    /// Return the index path.
    pub fn index_path(&self) -> &PathBuf {
        &self.index_path
    }
}

use engram_core::model::Manifest;
use engram_core::storage::GitStorage;

use crate::error::QueryError;
use crate::search::SearchEngine;

/// An entry in a file's reasoning trace.
#[derive(Debug, Clone)]
pub struct TraceEntry {
    pub manifest: Manifest,
    pub change_type: String,
}

/// Trace all engrams that touched a file, ordered by time.
pub fn trace_file(
    storage: &GitStorage,
    search: &SearchEngine,
    file_path: &str,
) -> Result<Vec<TraceEntry>, QueryError> {
    let results = search.search_by_file(storage, file_path, 100)?;

    let mut entries: Vec<TraceEntry> = results
        .into_iter()
        .map(|r| {
            // Try to find the specific change type for this file
            let change_type = "modified".to_string(); // Default; full data not in search result
            TraceEntry {
                manifest: r.manifest,
                change_type,
            }
        })
        .collect();

    // Sort by creation time (oldest first for a trace)
    entries.sort_by_key(|e| e.manifest.created_at);

    Ok(entries)
}

use std::collections::HashSet;

use engram_core::model::{EngramData, EngramId};
use engram_core::storage::GitStorage;

use crate::error::QueryError;

/// Differences between two engrams.
#[derive(Debug)]
pub struct EngramDiff {
    pub id_a: EngramId,
    pub id_b: EngramId,
    pub common_files: Vec<String>,
    pub only_a_files: Vec<String>,
    pub only_b_files: Vec<String>,
    pub token_delta: i64,
    pub cost_delta: Option<f64>,
}

/// Compare two engrams.
pub fn diff_engrams(
    storage: &GitStorage,
    id_a: &EngramId,
    id_b: &EngramId,
) -> Result<EngramDiff, QueryError> {
    let data_a = storage.read(id_a)?;
    let data_b = storage.read(id_b)?;

    compute_diff(id_a, id_b, &data_a, &data_b)
}

fn compute_diff(
    id_a: &EngramId,
    id_b: &EngramId,
    data_a: &EngramData,
    data_b: &EngramData,
) -> Result<EngramDiff, QueryError> {
    let files_a: HashSet<&str> = data_a
        .operations
        .file_changes
        .iter()
        .map(|f| f.path.as_str())
        .collect();
    let files_b: HashSet<&str> = data_b
        .operations
        .file_changes
        .iter()
        .map(|f| f.path.as_str())
        .collect();

    let common: Vec<String> = files_a
        .intersection(&files_b)
        .map(|s| s.to_string())
        .collect();
    let only_a: Vec<String> = files_a
        .difference(&files_b)
        .map(|s| s.to_string())
        .collect();
    let only_b: Vec<String> = files_b
        .difference(&files_a)
        .map(|s| s.to_string())
        .collect();

    let token_delta = data_b.manifest.token_usage.total_tokens as i64
        - data_a.manifest.token_usage.total_tokens as i64;

    let cost_delta = match (
        data_a.manifest.token_usage.cost_usd,
        data_b.manifest.token_usage.cost_usd,
    ) {
        (Some(a), Some(b)) => Some(b - a),
        _ => None,
    };

    Ok(EngramDiff {
        id_a: id_a.clone(),
        id_b: id_b.clone(),
        common_files: common,
        only_a_files: only_a,
        only_b_files: only_b,
        token_delta,
        cost_delta,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use engram_core::model::*;

    fn make_test_data(files: &[&str], tokens: u64, cost: Option<f64>) -> EngramData {
        EngramData {
            manifest: Manifest {
                id: EngramId::new(),
                version: 1,
                created_at: chrono::Utc::now(),
                finished_at: None,
                agent: AgentInfo {
                    name: "test".into(),
                    model: None,
                    version: None,
                },
                git_commits: Vec::new(),
                token_usage: TokenUsage {
                    total_tokens: tokens,
                    cost_usd: cost,
                    ..Default::default()
                },
                summary: None,
                tags: Vec::new(),
                capture_mode: CaptureMode::Import,
            },
            intent: Intent {
                original_request: "test".into(),
                interpreted_goal: None,
                summary: None,
                dead_ends: Vec::new(),
                decisions: Vec::new(),
            },
            transcript: Transcript {
                entries: Vec::new(),
            },
            operations: Operations {
                tool_calls: Vec::new(),
                file_changes: files
                    .iter()
                    .map(|f| FileChange {
                        path: f.to_string(),
                        change_type: FileChangeType::Modified,
                        lines_added: None,
                        lines_removed: None,
                    })
                    .collect(),
                shell_commands: Vec::new(),
            },
            lineage: Lineage::default(),
        }
    }

    #[test]
    fn test_diff_engrams() {
        let id_a = EngramId::new();
        let id_b = EngramId::new();
        let data_a = make_test_data(&["src/main.rs", "src/lib.rs"], 1000, Some(0.01));
        let data_b = make_test_data(&["src/main.rs", "tests/test.rs"], 2000, Some(0.03));

        let diff = compute_diff(&id_a, &id_b, &data_a, &data_b).unwrap();

        assert_eq!(diff.common_files, vec!["src/main.rs"]);
        assert!(diff.only_a_files.contains(&"src/lib.rs".to_string()));
        assert!(diff.only_b_files.contains(&"tests/test.rs".to_string()));
        assert_eq!(diff.token_delta, 1000);
        assert_eq!(diff.cost_delta, Some(0.02));
    }
}

use serde::{Deserialize, Serialize};

/// Type of node in the context graph.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum NodeType {
    Engram,
    File,
    Agent,
    Commit,
}

/// A node in the context graph.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GraphNode {
    pub id: String,
    pub node_type: NodeType,
    pub label: String,
}

/// Type of edge in the context graph.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum EdgeType {
    ModifiedBy,
    ProducedBy,
    UsedAgent,
    FollowsFrom,
    TouchedFile,
}

/// An edge in the context graph.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GraphEdge {
    pub from: String,
    pub to: String,
    pub edge_type: EdgeType,
}

/// The full context graph.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ContextGraph {
    pub nodes: Vec<GraphNode>,
    pub edges: Vec<GraphEdge>,
}

impl ContextGraph {
    /// Extract a subgraph centered on a node, up to a given depth.
    pub fn subgraph(&self, center_id: &str, depth: usize) -> ContextGraph {
        use std::collections::{HashSet, VecDeque};

        let mut visited = HashSet::new();
        let mut queue = VecDeque::new();
        queue.push_back((center_id.to_string(), 0));
        visited.insert(center_id.to_string());

        while let Some((current, d)) = queue.pop_front() {
            if d >= depth {
                continue;
            }
            for edge in &self.edges {
                let neighbor = if edge.from == current {
                    &edge.to
                } else if edge.to == current {
                    &edge.from
                } else {
                    continue;
                };
                if visited.insert(neighbor.clone()) {
                    queue.push_back((neighbor.clone(), d + 1));
                }
            }
        }

        let nodes: Vec<GraphNode> = self
            .nodes
            .iter()
            .filter(|n| visited.contains(&n.id))
            .cloned()
            .collect();
        let edges: Vec<GraphEdge> = self
            .edges
            .iter()
            .filter(|e| visited.contains(&e.from) && visited.contains(&e.to))
            .cloned()
            .collect();

        ContextGraph { nodes, edges }
    }

    /// Render as DOT format for Graphviz.
    pub fn to_dot(&self) -> String {
        let mut dot = String::from("digraph engram {\n  rankdir=LR;\n");

        for node in &self.nodes {
            let shape = match node.node_type {
                NodeType::Engram => "box",
                NodeType::File => "note",
                NodeType::Agent => "diamond",
                NodeType::Commit => "ellipse",
            };
            dot.push_str(&format!(
                "  \"{}\" [label=\"{}\" shape={}];\n",
                node.id, node.label, shape
            ));
        }

        for edge in &self.edges {
            let label = match edge.edge_type {
                EdgeType::ModifiedBy => "modified_by",
                EdgeType::ProducedBy => "produced_by",
                EdgeType::UsedAgent => "used_agent",
                EdgeType::FollowsFrom => "follows_from",
                EdgeType::TouchedFile => "touched_file",
            };
            dot.push_str(&format!(
                "  \"{}\" -> \"{}\" [label=\"{}\"];\n",
                edge.from, edge.to, label
            ));
        }

        dot.push_str("}\n");
        dot
    }
}

use std::collections::HashSet;

use engram_core::storage::GitStorage;

use super::model::*;
use crate::error::QueryError;

/// Build a context graph from all engrams in storage.
pub fn build_graph(storage: &GitStorage) -> Result<ContextGraph, QueryError> {
    let manifests = storage.list(&Default::default())?;
    let mut graph = ContextGraph::default();
    let mut seen_agents = HashSet::new();
    let mut seen_files = HashSet::new();
    let mut seen_commits = HashSet::new();

    for manifest in &manifests {
        let data = match storage.read(&manifest.id) {
            Ok(d) => d,
            Err(e) => {
                tracing::warn!("Failed to read engram {}: {e}", manifest.id);
                continue;
            }
        };

        let engram_node_id = format!("engram:{}", manifest.id.as_str());

        // Add engram node
        graph.nodes.push(GraphNode {
            id: engram_node_id.clone(),
            node_type: NodeType::Engram,
            label: manifest
                .summary
                .clone()
                .unwrap_or_else(|| manifest.id.as_str()[..8].to_string()),
        });

        // Add agent node + edge
        let agent_id = format!("agent:{}", manifest.agent.name);
        if seen_agents.insert(agent_id.clone()) {
            graph.nodes.push(GraphNode {
                id: agent_id.clone(),
                node_type: NodeType::Agent,
                label: manifest.agent.name.clone(),
            });
        }
        graph.edges.push(GraphEdge {
            from: engram_node_id.clone(),
            to: agent_id,
            edge_type: EdgeType::UsedAgent,
        });

        // Add file nodes + edges
        for fc in &data.operations.file_changes {
            let file_id = format!("file:{}", fc.path);
            if seen_files.insert(file_id.clone()) {
                graph.nodes.push(GraphNode {
                    id: file_id.clone(),
                    node_type: NodeType::File,
                    label: fc.path.clone(),
                });
            }
            graph.edges.push(GraphEdge {
                from: engram_node_id.clone(),
                to: file_id.clone(),
                edge_type: EdgeType::TouchedFile,
            });
            graph.edges.push(GraphEdge {
                from: file_id,
                to: engram_node_id.clone(),
                edge_type: EdgeType::ModifiedBy,
            });
        }

        // Add commit nodes + edges
        for sha in &data.lineage.git_commits {
            let commit_id = format!("commit:{}", &sha[..std::cmp::min(8, sha.len())]);
            if seen_commits.insert(commit_id.clone()) {
                graph.nodes.push(GraphNode {
                    id: commit_id.clone(),
                    node_type: NodeType::Commit,
                    label: sha[..std::cmp::min(8, sha.len())].to_string(),
                });
            }
            graph.edges.push(GraphEdge {
                from: engram_node_id.clone(),
                to: commit_id,
                edge_type: EdgeType::ProducedBy,
            });
        }

        // Add lineage edges
        if let Some(parent) = &data.lineage.parent_engram {
            let parent_node_id = format!("engram:{}", parent.as_str());
            graph.edges.push(GraphEdge {
                from: engram_node_id,
                to: parent_node_id,
                edge_type: EdgeType::FollowsFrom,
            });
        }
    }

    Ok(graph)
}

