use git2::Repository;

use crate::error::ProtocolError;

/// Refspec for fetching engram refs from remotes.
pub const ENGRAM_FETCH_REFSPEC: &str = "+refs/engrams/*:refs/engrams/*";

/// Refspec for pushing engram refs to remotes.
pub const ENGRAM_PUSH_REFSPEC: &str = "refs/engrams/*:refs/engrams/*";

/// Ensure the engram refspecs are configured for a remote.
pub fn ensure_refspecs(repo: &Repository, remote_name: &str) -> Result<bool, ProtocolError> {
    let remote = repo
        .find_remote(remote_name)
        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;

    let mut needs_fetch = true;
    let mut needs_push = true;

    // Check existing fetch refspecs
    if let Some(refspecs) = remote.fetch_refspecs().ok() {
        for i in 0..refspecs.len() {
            if let Some(spec) = refspecs.get(i) {
                if spec == ENGRAM_FETCH_REFSPEC {
                    needs_fetch = false;
                }
            }
        }
    }

    // Check existing push refspecs
    if let Some(refspecs) = remote.push_refspecs().ok() {
        for i in 0..refspecs.len() {
            if let Some(spec) = refspecs.get(i) {
                if spec == ENGRAM_PUSH_REFSPEC {
                    needs_push = false;
                }
            }
        }
    }

    drop(remote);

    let mut changed = false;

    if needs_fetch {
        repo.remote_add_fetch(remote_name, ENGRAM_FETCH_REFSPEC)?;
        changed = true;
    }

    if needs_push {
        repo.remote_add_push(remote_name, ENGRAM_PUSH_REFSPEC)?;
        changed = true;
    }

    Ok(changed)
}

/// Ensure refspecs for all remotes in the repository.
pub fn ensure_all_refspecs(repo: &Repository) -> Result<Vec<String>, ProtocolError> {
    let remotes = repo.remotes()?;
    let mut configured = Vec::new();

    for i in 0..remotes.len() {
        if let Some(name) = remotes.get(i) {
            if ensure_refspecs(repo, name)? {
                configured.push(name.to_string());
            }
        }
    }

    Ok(configured)
}

use git2::Repository;

use crate::error::ProtocolError;
use crate::refspec::{ensure_refspecs, ENGRAM_FETCH_REFSPEC, ENGRAM_PUSH_REFSPEC};

/// Options for push/fetch operations.
#[derive(Debug, Default)]
pub struct SyncOptions {
    /// Only sync these specific engram ref patterns (empty = all).
    pub refspecs: Vec<String>,
    /// Dry run — don't actually transfer data.
    pub dry_run: bool,
}

/// Result of a push operation.
#[derive(Debug)]
pub struct PushResult {
    pub remote: String,
    pub refs_pushed: usize,
}

/// Result of a fetch operation.
#[derive(Debug)]
pub struct FetchResult {
    pub remote: String,
    pub refs_fetched: usize,
}

/// Push engram refs to a remote.
pub fn push_engrams(
    repo: &Repository,
    remote_name: &str,
    opts: &SyncOptions,
) -> Result<PushResult, ProtocolError> {
    ensure_refspecs(repo, remote_name)?;

    let refspecs = if opts.refspecs.is_empty() {
        vec![ENGRAM_PUSH_REFSPEC.to_string()]
    } else {
        opts.refspecs.clone()
    };

    if opts.dry_run {
        // Count refs that would be pushed
        let refs = engram_core::storage::refs::list_engram_refs(repo)?;
        return Ok(PushResult {
            remote: remote_name.into(),
            refs_pushed: refs.len(),
        });
    }

    let mut remote = repo
        .find_remote(remote_name)
        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;

    let refspec_strs: Vec<&str> = refspecs.iter().map(|s| s.as_str()).collect();

    remote
        .push(&refspec_strs, None)
        .map_err(|e| ProtocolError::Sync(format!("Push failed: {e}")))?;

    // Count refs (approximate)
    let refs = engram_core::storage::refs::list_engram_refs(repo)?;

    Ok(PushResult {
        remote: remote_name.into(),
        refs_pushed: refs.len(),
    })
}

/// Fetch engram refs from a remote.
pub fn fetch_engrams(
    repo: &Repository,
    remote_name: &str,
    opts: &SyncOptions,
) -> Result<FetchResult, ProtocolError> {
    ensure_refspecs(repo, remote_name)?;

    let refspecs = if opts.refspecs.is_empty() {
        vec![ENGRAM_FETCH_REFSPEC.to_string()]
    } else {
        opts.refspecs.clone()
    };

    if opts.dry_run {
        return Ok(FetchResult {
            remote: remote_name.into(),
            refs_fetched: 0,
        });
    }

    let refs_before = engram_core::storage::refs::list_engram_refs(repo)?;

    let mut remote = repo
        .find_remote(remote_name)
        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;

    let refspec_strs: Vec<&str> = refspecs.iter().map(|s| s.as_str()).collect();

    remote
        .fetch(&refspec_strs, None, None)
        .map_err(|e| ProtocolError::Sync(format!("Fetch failed: {e}")))?;

    let refs_after = engram_core::storage::refs::list_engram_refs(repo)?;
    let new_refs = refs_after.len().saturating_sub(refs_before.len());

    Ok(FetchResult {
        remote: remote_name.into(),
        refs_fetched: new_refs,
    })
}

