use std::fs;
use std::path::{Path, PathBuf};

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

use crate::error::CoreError;
use crate::model::{AgentInfo, EngramId, TokenUsage};

const SESSION_FILE: &str = "engram-session";

/// Tracks an active recording session. Stored as JSON at `.git/engram-session`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ActiveSession {
    pub engram_id: EngramId,
    pub agent: AgentInfo,
    pub started_at: DateTime<Utc>,
    pub commits: Vec<String>,
    pub token_usage: TokenUsage,
}

impl ActiveSession {
    /// Create a new active session.
    pub fn new(engram_id: EngramId, agent: AgentInfo) -> Self {
        Self {
            engram_id,
            agent,
            started_at: Utc::now(),
            commits: Vec::new(),
            token_usage: TokenUsage::default(),
        }
    }

    /// Path to the session file inside the .git directory.
    fn session_path(git_dir: &Path) -> PathBuf {
        git_dir.join(SESSION_FILE)
    }

    /// Save the session to disk.
    pub fn save(&self, git_dir: &Path) -> Result<(), CoreError> {
        let path = Self::session_path(git_dir);
        let json = serde_json::to_string_pretty(self)
            .map_err(|e| CoreError::Config(format!("Failed to serialize session: {e}")))?;
        fs::write(&path, json)?;
        Ok(())
    }

    /// Load an active session if one exists.
    pub fn load(git_dir: &Path) -> Option<Self> {
        let path = Self::session_path(git_dir);
        let data = fs::read_to_string(&path).ok()?;
        serde_json::from_str(&data).ok()
    }

    /// Remove the session file.
    pub fn cleanup(git_dir: &Path) {
        let path = Self::session_path(git_dir);
        let _ = fs::remove_file(path);
    }

    /// Add a commit SHA to the session and re-save.
    pub fn add_commit(&mut self, sha: &str, git_dir: &Path) -> Result<(), CoreError> {
        self.commits.push(sha.to_string());
        self.save(git_dir)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn test_session_save_load_cleanup() {
        let tmp = TempDir::new().unwrap();
        let git_dir = tmp.path();

        let session = ActiveSession::new(
            EngramId::new(),
            AgentInfo {
                name: "test-agent".into(),
                model: Some("gpt-4".into()),
                version: None,
            },
        );

        // Save
        session.save(git_dir).unwrap();

        // Load
        let loaded = ActiveSession::load(git_dir).unwrap();
        assert_eq!(loaded.engram_id, session.engram_id);
        assert_eq!(loaded.agent.name, "test-agent");
        assert!(loaded.commits.is_empty());

        // Add commit
        let mut loaded = loaded;
        loaded.add_commit("abc123", git_dir).unwrap();
        let reloaded = ActiveSession::load(git_dir).unwrap();
        assert_eq!(reloaded.commits, vec!["abc123"]);

        // Cleanup
        ActiveSession::cleanup(git_dir);
        assert!(ActiveSession::load(git_dir).is_none());
    }
}

use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;

use crate::error::CoreError;

const HOOKS: &[&str] = &["prepare-commit-msg", "post-commit"];

/// Install engram git hooks into the repository's hooks directory.
///
/// For each hook, if an existing hook script is present, it is renamed
/// to `<hook>.pre-engram` and the new hook chains to it.
pub fn install_hooks(git_dir: &Path) -> Result<(), CoreError> {
    let hooks_dir = git_dir.join("hooks");
    fs::create_dir_all(&hooks_dir)?;

    for hook_name in HOOKS {
        let hook_path = hooks_dir.join(hook_name);
        let backup_path = hooks_dir.join(format!("{hook_name}.pre-engram"));

        // If there's an existing hook (and it's not ours), back it up
        if hook_path.exists() {
            let content = fs::read_to_string(&hook_path)?;
            if !content.contains("engram hook-handler") {
                fs::rename(&hook_path, &backup_path)?;
            }
        }

        let script = generate_hook_script(hook_name, backup_path.exists());
        fs::write(&hook_path, script)?;
        fs::set_permissions(&hook_path, fs::Permissions::from_mode(0o755))?;
    }

    Ok(())
}

/// Uninstall engram hooks, restoring originals if they were backed up.
pub fn uninstall_hooks(git_dir: &Path) -> Result<(), CoreError> {
    let hooks_dir = git_dir.join("hooks");

    for hook_name in HOOKS {
        let hook_path = hooks_dir.join(hook_name);
        let backup_path = hooks_dir.join(format!("{hook_name}.pre-engram"));

        if hook_path.exists() {
            let content = fs::read_to_string(&hook_path).unwrap_or_default();
            if content.contains("engram hook-handler") {
                fs::remove_file(&hook_path)?;
            }
        }

        if backup_path.exists() {
            fs::rename(&backup_path, &hook_path)?;
        }
    }

    Ok(())
}

fn generate_hook_script(hook_name: &str, has_backup: bool) -> String {
    let mut script = String::from("#!/bin/sh\n");
    script.push_str("# Engram git hook — auto-generated, do not edit\n\n");

    // Chain to existing hook if backed up
    if has_backup {
        script.push_str(&format!(
            "# Run original hook\n\
             if [ -x \"$(dirname \"$0\")/{hook_name}.pre-engram\" ]; then\n\
             \t\"$(dirname \"$0\")/{hook_name}.pre-engram\" \"$@\"\n\
             \tHOOK_EXIT=$?\n\
             \tif [ $HOOK_EXIT -ne 0 ]; then\n\
             \t\texit $HOOK_EXIT\n\
             \tfi\n\
             fi\n\n"
        ));
    }

    // Run engram hook handler (fail silently — hooks should not break git)
    script.push_str(&format!(
        "# Run engram hook handler\n\
         if command -v engram >/dev/null 2>&1; then\n\
         \tengram hook-handler {hook_name} \"$@\" || true\n\
         fi\n"
    ));

    script
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn test_install_hooks() {
        let tmp = TempDir::new().unwrap();
        let git_dir = tmp.path();
        fs::create_dir_all(git_dir.join("hooks")).unwrap();

        install_hooks(git_dir).unwrap();

        for hook_name in HOOKS {
            let hook_path = git_dir.join("hooks").join(hook_name);
            assert!(hook_path.exists(), "Hook {hook_name} should exist");
            let content = fs::read_to_string(&hook_path).unwrap();
            assert!(content.contains("engram hook-handler"));
        }
    }

    #[test]
    fn test_install_chains_existing() {
        let tmp = TempDir::new().unwrap();
        let git_dir = tmp.path();
        let hooks_dir = git_dir.join("hooks");
        fs::create_dir_all(&hooks_dir).unwrap();

        // Create an existing hook
        let existing = hooks_dir.join("prepare-commit-msg");
        fs::write(&existing, "#!/bin/sh\necho original\n").unwrap();

        install_hooks(git_dir).unwrap();

        // Original should be backed up
        let backup = hooks_dir.join("prepare-commit-msg.pre-engram");
        assert!(backup.exists());
        let backup_content = fs::read_to_string(&backup).unwrap();
        assert!(backup_content.contains("echo original"));

        // New hook should chain
        let new_content = fs::read_to_string(&existing).unwrap();
        assert!(new_content.contains("pre-engram"));
        assert!(new_content.contains("engram hook-handler"));
    }

    #[test]
    fn test_uninstall_hooks() {
        let tmp = TempDir::new().unwrap();
        let git_dir = tmp.path();
        let hooks_dir = git_dir.join("hooks");
        fs::create_dir_all(&hooks_dir).unwrap();

        // Create existing hook, install, then uninstall
        let existing = hooks_dir.join("prepare-commit-msg");
        fs::write(&existing, "#!/bin/sh\necho original\n").unwrap();

        install_hooks(git_dir).unwrap();
        uninstall_hooks(git_dir).unwrap();

        // Original should be restored
        let content = fs::read_to_string(&existing).unwrap();
        assert!(content.contains("echo original"));
        assert!(!hooks_dir.join("prepare-commit-msg.pre-engram").exists());
    }
}

use std::fs;
use std::path::Path;

use crate::error::CoreError;

use super::session::ActiveSession;

/// Handle the `prepare-commit-msg` hook.
///
/// If an active engram session exists, appends Engram trailers to the commit message.
pub fn handle_prepare_commit_msg(msg_file: &Path, git_dir: &Path) -> Result<(), CoreError> {
    let session = match ActiveSession::load(git_dir) {
        Some(s) => s,
        None => return Ok(()), // No active session, nothing to do
    };

    let mut msg = fs::read_to_string(msg_file)?;

    // Don't add trailers if they're already there
    if msg.contains("Engram-Id:") {
        return Ok(());
    }

    // Ensure blank line before trailers
    if !msg.ends_with('\n') {
        msg.push('\n');
    }
    msg.push('\n');

    msg.push_str(&format!("Engram-Id: {}\n", session.engram_id.as_str()));
    msg.push_str(&format!(
        "Engram-Agent: {}{}\n",
        session.agent.name,
        session
            .agent
            .model
            .as_ref()
            .map(|m| format!("/{m}"))
            .unwrap_or_default()
    ));
    msg.push_str(&format!(
        "Engram-Tokens: {}\n",
        session.token_usage.total_tokens
    ));
    if let Some(cost) = session.token_usage.cost_usd {
        msg.push_str(&format!("Engram-Cost: ${cost:.2}\n"));
    }

    fs::write(msg_file, msg)?;
    Ok(())
}

/// Handle the `post-commit` hook.
///
/// If an active engram session exists, records the new commit SHA.
pub fn handle_post_commit(git_dir: &Path) -> Result<(), CoreError> {
    let mut session = match ActiveSession::load(git_dir) {
        Some(s) => s,
        None => return Ok(()),
    };

    // Read HEAD to get the new commit SHA
    let repo = git2::Repository::open(git_dir.parent().unwrap_or(git_dir))?;
    let head = repo.head()?;
    let sha = head
        .target()
        .map(|oid| oid.to_string())
        .unwrap_or_default();

    if !sha.is_empty() {
        session.add_commit(&sha, git_dir)?;
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{AgentInfo, EngramId, TokenUsage};
    use tempfile::TempDir;

    fn make_session() -> ActiveSession {
        let mut session = ActiveSession::new(
            EngramId::new(),
            AgentInfo {
                name: "claude-code".into(),
                model: Some("claude-sonnet-4-5".into()),
                version: None,
            },
        );
        session.token_usage = TokenUsage {
            input_tokens: 1000,
            output_tokens: 500,
            total_tokens: 1500,
            cost_usd: Some(0.02),
            ..Default::default()
        };
        session
    }

    #[test]
    fn test_prepare_commit_msg_no_session() {
        let tmp = TempDir::new().unwrap();
        let msg_file = tmp.path().join("COMMIT_EDITMSG");
        fs::write(&msg_file, "Initial commit\n").unwrap();

        // No session file — should be a no-op
        handle_prepare_commit_msg(&msg_file, tmp.path()).unwrap();

        let content = fs::read_to_string(&msg_file).unwrap();
        assert_eq!(content, "Initial commit\n");
    }

    #[test]
    fn test_prepare_commit_msg_with_session() {
        let tmp = TempDir::new().unwrap();
        let msg_file = tmp.path().join("COMMIT_EDITMSG");
        fs::write(&msg_file, "Add auth feature\n").unwrap();

        let session = make_session();
        session.save(tmp.path()).unwrap();

        handle_prepare_commit_msg(&msg_file, tmp.path()).unwrap();

        let content = fs::read_to_string(&msg_file).unwrap();
        assert!(content.contains("Engram-Id:"));
        assert!(content.contains("Engram-Agent: claude-code/claude-sonnet-4-5"));
        assert!(content.contains("Engram-Tokens: 1500"));
        assert!(content.contains("Engram-Cost: $0.02"));
    }

    #[test]
    fn test_prepare_commit_msg_idempotent() {
        let tmp = TempDir::new().unwrap();
        let msg_file = tmp.path().join("COMMIT_EDITMSG");
        fs::write(&msg_file, "Add auth\n\nEngram-Id: existing\n").unwrap();

        let session = make_session();
        session.save(tmp.path()).unwrap();

        handle_prepare_commit_msg(&msg_file, tmp.path()).unwrap();

        let content = fs::read_to_string(&msg_file).unwrap();
        // Should not duplicate trailers
        assert_eq!(content.matches("Engram-Id:").count(), 1);
    }
}

