use std::collections::BTreeMap;

use anyhow::{Context, Result};
use engram_core::storage::{GitStorage, ListOptions};

use crate::output::OutputFormat;

pub fn run(format: OutputFormat) -> Result<()> {
    let storage = GitStorage::discover().context("Not inside a Git repository")?;

    if !storage.is_initialized() {
        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
    }

    let manifests = storage
        .list(&ListOptions::default())
        .context("Failed to list engrams")?;

    if manifests.is_empty() {
        println!("No engrams found.");
        return Ok(());
    }

    let total = manifests.len();
    let mut total_tokens: u64 = 0;
    let mut total_cost: f64 = 0.0;
    let mut by_agent: BTreeMap<String, (usize, u64, f64)> = BTreeMap::new();
    let mut by_mode: BTreeMap<String, usize> = BTreeMap::new();

    let earliest = manifests.last().map(|m| m.created_at);
    let latest = manifests.first().map(|m| m.created_at);

    for m in &manifests {
        total_tokens += m.token_usage.total_tokens;
        total_cost += m.token_usage.cost_usd.unwrap_or(0.0);

        let entry = by_agent.entry(m.agent.name.clone()).or_default();
        entry.0 += 1;
        entry.1 += m.token_usage.total_tokens;
        entry.2 += m.token_usage.cost_usd.unwrap_or(0.0);

        *by_mode
            .entry(format!("{:?}", m.capture_mode))
            .or_default() += 1;
    }

    match format {
        OutputFormat::Json => {
            let stats = serde_json::json!({
                "total_engrams": total,
                "total_tokens": total_tokens,
                "total_cost_usd": total_cost,
                "earliest": earliest,
                "latest": latest,
                "by_agent": by_agent.iter().map(|(name, (count, tokens, cost))| {
                    serde_json::json!({
                        "agent": name,
                        "count": count,
                        "tokens": tokens,
                        "cost_usd": cost,
                    })
                }).collect::<Vec<_>>(),
                "by_capture_mode": by_mode,
            });
            println!("{}", serde_json::to_string_pretty(&stats).unwrap());
        }
        OutputFormat::Text => {
            println!("Engram Statistics");
            println!("=================");
            println!("Total engrams:  {total}");
            println!("Total tokens:   {total_tokens}");
            println!("Total cost:     ${total_cost:.2}");
            if let (Some(e), Some(l)) = (earliest, latest) {
                println!(
                    "Date range:     {} to {}",
                    e.format("%Y-%m-%d"),
                    l.format("%Y-%m-%d")
                );
            }
            println!();

            println!("By Agent:");
            for (name, (count, tokens, cost)) in &by_agent {
                println!("  {name}: {count} engrams, {tokens} tokens, ${cost:.2}");
            }
            println!();

            println!("By Capture Mode:");
            for (mode, count) in &by_mode {
                println!("  {mode}: {count}");
            }
        }
    }

    Ok(())
}

use anyhow::{Context, Result};
use chrono::{Duration, Utc};
use clap::Args;
use engram_core::storage::{GitStorage, ListOptions};

#[derive(Args)]
pub struct GcArgs {
    /// Delete engrams older than this duration (e.g. "30d", "6m", "1y")
    #[arg(long)]
    pub older_than: Option<String>,

    /// Preview what would be deleted without actually deleting
    #[arg(long)]
    pub dry_run: bool,

    /// Skip confirmation prompt
    #[arg(long, short)]
    pub yes: bool,
}

pub fn run(args: &GcArgs) -> Result<()> {
    let storage = GitStorage::discover().context("Not inside a Git repository")?;

    if !storage.is_initialized() {
        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
    }

    let cutoff = if let Some(duration_str) = &args.older_than {
        let dur = parse_duration(duration_str)?;
        Some(Utc::now() - dur)
    } else {
        None
    };

    let manifests = storage
        .list(&ListOptions::default())
        .context("Failed to list engrams")?;

    let to_delete: Vec<_> = manifests
        .iter()
        .filter(|m| {
            if let Some(cutoff) = cutoff {
                m.created_at < cutoff
            } else {
                false
            }
        })
        .collect();

    if to_delete.is_empty() {
        println!("No engrams match the deletion criteria.");
        return Ok(());
    }

    println!(
        "{} engram(s) to {}:",
        to_delete.len(),
        if args.dry_run { "delete (dry run)" } else { "delete" }
    );
    for m in &to_delete {
        println!(
            "  {} {} [{}] {}",
            &m.id.as_str()[..8],
            m.created_at.format("%Y-%m-%d %H:%M"),
            m.agent.name,
            m.summary.as_deref().unwrap_or("(no summary)")
        );
    }

    if args.dry_run {
        println!("\nDry run — no engrams were deleted.");
        return Ok(());
    }

    if !args.yes {
        eprintln!("\nUse --yes to confirm deletion.");
        return Ok(());
    }

    let mut deleted = 0;
    for m in &to_delete {
        match storage.delete(m.id.as_str()) {
            Ok(()) => deleted += 1,
            Err(e) => eprintln!("Failed to delete {}: {e}", &m.id.as_str()[..8]),
        }
    }

    println!("\nDeleted {deleted} engram(s).");
    Ok(())
}

fn parse_duration(s: &str) -> Result<Duration> {
    let s = s.trim();
    if s.is_empty() {
        anyhow::bail!("Empty duration string");
    }

    let (num_str, unit) = s.split_at(s.len() - 1);
    let num: i64 = num_str
        .parse()
        .with_context(|| format!("Invalid duration number: {num_str}"))?;

    match unit {
        "d" => Ok(Duration::days(num)),
        "w" => Ok(Duration::weeks(num)),
        "m" => Ok(Duration::days(num * 30)),
        "y" => Ok(Duration::days(num * 365)),
        _ => anyhow::bail!("Unknown duration unit '{unit}'. Use d (days), w (weeks), m (months), y (years)."),
    }
}

use anyhow::{Context, Result};
use clap::Args;
use engram_core::storage::GitStorage;
use engram_query::search::SearchEngine;

use crate::output::OutputFormat;

#[derive(Args)]
pub struct BlameArgs {
    /// File path to find reasoning history for
    pub file: String,

    /// Maximum number of results
    #[arg(short = 'n', long, default_value = "20")]
    pub limit: usize,
}

pub fn run(args: &BlameArgs, format: OutputFormat) -> Result<()> {
    let storage = GitStorage::discover().context("Not inside a Git repository")?;

    if !storage.is_initialized() {
        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
    }

    let search = SearchEngine::open(&storage).context("Failed to open search index")?;
    let results = search
        .search_by_file(&storage, &args.file, args.limit)
        .context("Search failed")?;

    if results.is_empty() {
        println!("No engrams found that touched '{}'.", args.file);
        return Ok(());
    }

    match format {
        OutputFormat::Json => {
            let entries: Vec<_> = results
                .iter()
                .map(|r| {
                    // Get actual change type
                    let change_info = storage.read(r.manifest.id.as_str()).ok().and_then(|data| {
                        data.operations
                            .file_changes
                            .iter()
                            .find(|fc| fc.path == args.file)
                            .map(|fc| {
                                serde_json::json!({
                                    "change_type": format!("{:?}", fc.change_type),
                                    "lines_added": fc.lines_added,
                                    "lines_removed": fc.lines_removed,
                                })
                            })
                    });

                    serde_json::json!({
                        "engram_id": r.manifest.id.as_str(),
                        "created_at": r.manifest.created_at,
                        "agent": r.manifest.agent.name,
                        "summary": r.manifest.summary,
                        "intent": r.manifest.summary,
                        "change": change_info,
                    })
                })
                .collect();
            println!("{}", serde_json::to_string_pretty(&entries).unwrap());
        }
        OutputFormat::Text => {
            println!("Reasoning blame for: {}", args.file);
            println!("{}", "=".repeat(40 + args.file.len()));
            println!();

            for r in &results {
                let m = &r.manifest;
                let short_id = &m.id.as_str()[..8];
                let date = m.created_at.format("%Y-%m-%d %H:%M");
                let summary = m.summary.as_deref().unwrap_or("(no summary)");

                // Get change type from full data
                let change_type = storage
                    .read(m.id.as_str())
                    .ok()
                    .and_then(|data| {
                        data.operations
                            .file_changes
                            .iter()
                            .find(|fc| fc.path == args.file)
                            .map(|fc| format!("{:?}", fc.change_type).to_lowercase())
                    })
                    .unwrap_or_else(|| "touched".to_string());

                println!("{short_id} {date} [{change_type}] {}", m.agent.name);
                println!("  {summary}");

                // Show intent if we can read it
                if let Ok(data) = storage.read(m.id.as_str()) {
                    let intent = &data.intent.original_request;
                    if intent != summary {
                        println!("  Intent: \"{intent}\"");
                    }
                    if !data.intent.dead_ends.is_empty() {
                        let dead_ends: Vec<_> =
                            data.intent.dead_ends.iter().map(|d| &d.approach).collect();
                        println!("  Dead ends: {}", dead_ends.iter().map(|s| s.as_str()).collect::<Vec<_>>().join(", "));
                    }
                }
                println!();
            }
        }
    }

    Ok(())
}

