  input: unknown;
  output_summary?: string;
  duration_ms?: number;
  is_error: boolean;
}

export interface FileChange {
  path: string;
  change_type: string;
  lines_added?: number;
  lines_removed?: number;
}

export interface ShellCommand {
  timestamp: string;
