  exit_code?: number;
  duration_ms?: number;
}

export interface Operations {
  tool_calls: ToolCall[];
  file_changes: FileChange[];
  shell_commands: ShellCommand[];
}

export interface Lineage {
  parent_engram?: string;
  child_engrams: string[];
  related_engrams: unknown[];
  git_commits: string[];
  branch?: string;
}

export interface Manifest {
  id: string;
  version: number;
  created_at: string;
  finished_at?: string;
  agent: AgentInfo;
  git_commits: string[];
  token_usage: TokenUsage;
  summary?: string;
  tags: string[];
  capture_mode: CaptureMode;
}

export interface EngramData {
  manifest: Manifest;
  intent: Intent;
  transcript: Transcript;
  operations: Operations;
  lineage: Lineage;
}

export function newEngramId(): string {
  return randomUUID().replace(/-/g, "");
}

export function intentToMarkdown(intent: Intent): string {
  const lines: string[] = [
    "# Intent",
    "",
    "## Original Request",
    "",
    intent.original_request,
    "",
  ];

  if (intent.summary) {
    lines.push("## Summary", "", intent.summary, "");
  }

  if (intent.dead_ends.length > 0) {
    lines.push("## Dead Ends", "");
    for (const de of intent.dead_ends) {
      lines.push(`- **${de.approach}**: ${de.reason}`);
    }
    lines.push("");
  }

  if (intent.decisions.length > 0) {
    lines.push("## Decisions", "");
    for (const d of intent.decisions) {
      lines.push(`- **${d.description}**: ${d.rationale}`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

export function transcriptToJsonl(transcript: Transcript): string {
  return transcript.entries.map((e) => JSON.stringify(e)).join("\n") + "\n";
}

/**
 * Git-native storage for engrams using git CLI commands (via simple-git).
 */

import { execSync } from "child_process";
import { readFileSync, readdirSync, statSync } from "fs";
import { join } from "path";
import type { EngramData, Manifest } from "./model.js";
import { intentToMarkdown, transcriptToJsonl } from "./model.js";

const ENGRAM_REF_PREFIX = "refs/engrams/";

function refName(engramId: string): string {
  const prefix = engramId.slice(0, 2);
  return `refs/engrams/${prefix}/${engramId}`;
}

function gitCmd(repoPath: string, args: string, input?: string): string {
  const opts: Parameters<typeof execSync>[1] = {
    cwd: repoPath,
    encoding: "utf-8" as const,
    maxBuffer: 50 * 1024 * 1024,
    stdio: input ? ["pipe", "pipe", "pipe"] : ["pipe", "pipe", "pipe"],
  };
  if (input) {
    (opts as Record<string, unknown>).input = input;
  }
  return execSync(`git ${args}`, opts).toString().trim();
}

export class GitStorage {
  private repoPath: string;

  constructor(repoPath: string) {
    this.repoPath = repoPath;
  }

  static open(path: string): GitStorage {
    return new GitStorage(path);
  }

  static discover(startPath: string = "."): GitStorage {
    const toplevel = execSync("git rev-parse --show-toplevel", {
      cwd: startPath,
      encoding: "utf-8",
    }).trim();
    return new GitStorage(toplevel);
  }

  /**
   * Store an engram as Git objects and create a ref. Returns the engram ID.
   */
  create(data: EngramData): string {
    const manifestJson = JSON.stringify(data.manifest, null, 2);
    const intentMd = intentToMarkdown(data.intent);
    const transcriptJsonl = transcriptToJsonl(data.transcript);
    const operationsJson = JSON.stringify(data.operations, null, 2);
    const lineageJson = JSON.stringify(data.lineage, null, 2);

    // Create blobs
    const manifestOid = gitCmd(this.repoPath, "hash-object -w --stdin", manifestJson);
    const intentOid = gitCmd(this.repoPath, "hash-object -w --stdin", intentMd);
    const transcriptOid = gitCmd(this.repoPath, "hash-object -w --stdin", transcriptJsonl);
    const operationsOid = gitCmd(this.repoPath, "hash-object -w --stdin", operationsJson);
    const lineageOid = gitCmd(this.repoPath, "hash-object -w --stdin", lineageJson);

    // Build tree via mktree
    const treeInput = [
      `100644 blob ${intentOid}\tintent.md`,
      `100644 blob ${lineageOid}\tlineage.json`,
      `100644 blob ${manifestOid}\tmanifest.json`,
      `100644 blob ${operationsOid}\toperations.json`,
      `100644 blob ${transcriptOid}\ttranscript.jsonl`,
    ].join("\n");

    const treeOid = gitCmd(this.repoPath, "mktree", treeInput);

    // Create commit
    const summary = data.manifest.summary || "engram session";
    const commitOid = gitCmd(
      this.repoPath,
      `commit-tree ${treeOid} -m "engram: ${summary}"`,
    );

    // Create ref
    const ref = refName(data.manifest.id);
    gitCmd(this.repoPath, `update-ref ${ref} ${commitOid}`);

    return data.manifest.id;
  }

  /**
   * Read an engram by its ID (or prefix).
   */
  read(idOrPrefix: string): EngramData {
    const resolvedRef = this.resolve(idOrPrefix);
    const commitOid = gitCmd(this.repoPath, `rev-parse ${resolvedRef}`);

    // Get tree from commit
    const treeOid = gitCmd(this.repoPath, `rev-parse ${commitOid}^{tree}`);

    // Read each blob
    const manifestJson = gitCmd(this.repoPath, `cat-file blob ${treeOid}:manifest.json`);

    const manifest: Manifest = JSON.parse(manifestJson);

    return {
      manifest,
      intent: {
        original_request: "",
        dead_ends: [],
        decisions: [],
      },
      transcript: { entries: [] },
      operations: { tool_calls: [], file_changes: [], shell_commands: [] },
      lineage: { child_engrams: [], related_engrams: [], git_commits: manifest.git_commits || [] },
    };
  }

  /**
   * Read only the manifest (fast path).
   */
  readManifest(idOrPrefix: string): Manifest {
    return this.read(idOrPrefix).manifest;
  }

  /**
   * List all engrams, most recent first.
   */
  list(): Manifest[] {
    let output: string;
    try {
      output = gitCmd(
        this.repoPath,
        `for-each-ref --format="%(refname)" refs/engrams/`,
      );
    } catch {
      return [];
    }

    if (!output.trim()) return [];

    const manifests: Manifest[] = [];
    for (const ref of output.split("\n")) {
      if (!ref.trim()) continue;
      try {
        const commitOid = gitCmd(this.repoPath, `rev-parse ${ref}`);
        const treeOid = gitCmd(this.repoPath, `rev-parse ${commitOid}^{tree}`);
        const manifestJson = gitCmd(this.repoPath, `cat-file blob ${treeOid}:manifest.json`);
        manifests.push(JSON.parse(manifestJson));
      } catch {
        continue;
      }
    }

    manifests.sort(
      (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
    );

    return manifests;
  }

  /**
   * Delete an engram by removing its ref.
   */
  delete(idOrPrefix: string): void {
    const resolvedRef = this.resolve(idOrPrefix);
    gitCmd(this.repoPath, `update-ref -d ${resolvedRef}`);
  }

  private resolve(idOrPrefix: string): string {
    // Try exact match
    const exactRef = refName(idOrPrefix);
    try {
      gitCmd(this.repoPath, `rev-parse --verify ${exactRef}`);
      return exactRef;
    } catch {
      // fall through
    }

    // Try prefix match
    let output: string;
    try {
      output = gitCmd(
        this.repoPath,
        `for-each-ref --format="%(refname)" refs/engrams/`,
      );
    } catch {
      throw new Error(`Engram not found: ${idOrPrefix}`);
    }

    const matches: string[] = [];
    for (const ref of output.split("\n")) {
      if (!ref.trim()) continue;
      const parts = ref.replace(ENGRAM_REF_PREFIX, "").split("/");
      if (parts.length === 2 && parts[1].startsWith(idOrPrefix)) {
        matches.push(ref);
      }
    }

    if (matches.length === 0) {
      throw new Error(`Engram not found: ${idOrPrefix}`);
    }
    if (matches.length > 1) {
      throw new Error(`Ambiguous engram prefix: ${idOrPrefix} (${matches.length} matches)`);
    }

    return matches[0];
  }
}

/**
 * Fluent session builder for creating engrams programmatically.
 */

import type {
  AgentInfo,
  DeadEnd,
  Decision,
  EngramData,
  FileChange,
  ShellCommand,
  TokenUsage,
  ToolCall,
  TranscriptEntry,
} from "./model.js";
import { defaultTokenUsage, newEngramId } from "./model.js";
import { GitStorage } from "./storage.js";

const CHANGE_TYPE_MAP: Record<string, string> = {
  created: "Created",
  create: "Created",
  new: "Created",
  modified: "Modified",
  modify: "Modified",
  changed: "Modified",
  deleted: "Deleted",
  delete: "Deleted",
  removed: "Deleted",
};

export class EngramSession {
  private agent: AgentInfo;
  private _transcript: TranscriptEntry[] = [];
  private _toolCalls: ToolCall[] = [];
  private _fileChanges: FileChange[] = [];
  private _shellCommands: ShellCommand[] = [];
  private _deadEnds: DeadEnd[] = [];
  private _decisions: Decision[] = [];
  private _tokenUsage: TokenUsage;
  private _originalRequest?: string;
  private _summary?: string;
  private _tags: string[] = [];
  private _parent?: string;
  private _startedAt: string;

  private constructor(agentName: string, model?: string) {
    this.agent = { name: agentName, model };
    this._tokenUsage = defaultTokenUsage();
    this._startedAt = new Date().toISOString();
  }

  /**
   * Create a new session for a given agent and optional model.
   */
  static begin(agentName: string, model?: string): EngramSession {
    return new EngramSession(agentName, model);
  }

  /**
   * Log a message (user, assistant, system, or tool).
   */
  logMessage(role: string, content: string): EngramSession {
    if (role === "user" && this._originalRequest === undefined) {
      this._originalRequest = content;
    }

    this._transcript.push({
      timestamp: new Date().toISOString(),
      role,
      content: { type: "text", text: content },
    });
    return this;
  }

  /**
   * Log a tool call.
   */
  logToolCall(
    toolName: string,
    input: string | Record<string, unknown>,
    outputSummary?: string,
  ): EngramSession {
    let parsedInput: unknown;
    if (typeof input === "string") {
      try {
        parsedInput = JSON.parse(input);
      } catch {
        parsedInput = input;
      }
    } else {
      parsedInput = input;
    }

    this._toolCalls.push({
      timestamp: new Date().toISOString(),
      tool_name: toolName,
      input: parsedInput,
      output_summary: outputSummary,
      is_error: false,
    });
    return this;
  }

  /**
   * Log a file change.
   */
  logFileChange(path: string, changeType: string): EngramSession {
    const ct = CHANGE_TYPE_MAP[changeType.toLowerCase()] || "Modified";
    this._fileChanges.push({ path, change_type: ct });
    return this;
  }

  /**
   * Log a shell command execution.
   */
  logShellCommand(
    command: string,
    exitCode?: number,
    durationMs?: number,
  ): EngramSession {
    this._shellCommands.push({
      timestamp: new Date().toISOString(),
      command,
      exit_code: exitCode,
      duration_ms: durationMs,
    });
    return this;
  }

  /**
   * Log a rejected approach (dead end).
   */
  logRejection(approach: string, reason: string): EngramSession {
    this._deadEnds.push({ approach, reason });
    return this;
  }

  /**
   * Log a decision made during the session.
   */
  logDecision(description: string, rationale: string): EngramSession {
    this._decisions.push({ description, rationale });
    return this;
  }

  /**
   * Add token usage. Accumulates across multiple calls.
   */
  addTokens(
    inputTokens: number,
    outputTokens: number,
    costUsd?: number,
  ): EngramSession {
    this._tokenUsage.input_tokens += inputTokens;
    this._tokenUsage.output_tokens += outputTokens;
    this._tokenUsage.total_tokens += inputTokens + outputTokens;
    if (costUsd !== undefined) {
      this._tokenUsage.cost_usd = (this._tokenUsage.cost_usd || 0) + costUsd;
    }
    return this;
  }

  /**
   * Set a summary for this session.
   */
  setSummary(summary: string): EngramSession {
    this._summary = summary;
    return this;
  }

  /**
   * Add a tag.
   */
  tag(tagName: string): EngramSession {
    this._tags.push(tagName);
    return this;
  }

  /**
   * Set the parent engram ID.
   */
  parent(parentId: string): EngramSession {
    this._parent = parentId;
    return this;
  }

  /**
   * Build the EngramData without storing it.
   */
  build(gitSha?: string, summary?: string): EngramData {
    const engramId = newEngramId();
    const finishedAt = new Date().toISOString();
    const finalSummary = summary || this._summary || this._originalRequest;
    const gitCommits = gitSha ? [gitSha] : [];

    return {
      manifest: {
        id: engramId,
        version: 1,
        created_at: this._startedAt,
        finished_at: finishedAt,
        agent: this.agent,
        git_commits: gitCommits,
        token_usage: this._tokenUsage,
        summary: finalSummary,
        tags: this._tags,
        capture_mode: "Sdk",
      },
      intent: {
        original_request: this._originalRequest || "SDK session",
        summary: finalSummary,
        dead_ends: this._deadEnds,
        decisions: this._decisions,
      },
      transcript: {
        entries: this._transcript,
      },
      operations: {
        tool_calls: this._toolCalls,
        file_changes: this._fileChanges,
        shell_commands: this._shellCommands,
      },
      lineage: {
        parent_engram: this._parent,
        child_engrams: [],
        related_engrams: [],
        git_commits: gitCommits,
      },
    };
  }

  /**
   * Finalize and store the engram in Git. Returns the engram ID.
   */
  commit(gitSha?: string, summary?: string, storage?: GitStorage): string {
    const data = this.build(gitSha, summary);
    const store = storage || GitStorage.discover();
    return store.create(data);
  }
}

export { EngramSession } from "./session.js";
